}

const extractTimelineEvents = async (summary: string): Promise<TimelineEvent[]> => {
  const truncatedSummary = summary.length > 50000 ? summary.substring(0, 50000) + "...(truncated)" : summary;
  const prompt = `From the following case summary, extract key judicial events in chronological order. Identify filing dates, motion submissions, court dates (hearings, trials), and rulings. For each event, provide the exact date as a string (e.g., "January 15, 2023"), a brief description, and categorize it as 'filing', 'motion', 'court_date', 'ruling', or 'other'. If multiple events occur on the same date, combine them into a single entry if logically related, or list separately if distinct.\n\nSummary:\n${truncatedSummary}`;
  try {
      const response: GenerateContentResponse = await ai.models.generateContent({
          model: 'gemini-2.5-flash', // Use lighter model for structuring
          contents: prompt,
          config: {
              responseMimeType: "application/json",
              responseSchema: {
                  type: Type.OBJECT,
                  properties: {
                      events: {
                          type: Type.ARRAY,
                          description: 'Chronological list of key case events.',
                          items: {
                              type: Type.OBJECT,
                              properties: {
                                  date: { type: Type.STRING, description: 'The exact date of the event (e.g., "January 15, 2023").' },
                                  description: { type: Type.STRING, description: 'A brief description of the event.' },
                                  type: {
                                      type: Type.STRING,
                                      description: 'Category of the event.',
                                      enum: ['filing', 'motion', 'court_date', 'ruling', 'other']
                                  }
                              },
                              required: ['date', 'description', 'type']
                          }
                      }
                  }
              }
          }
      });
      const parsed = safeParseJSON<{ events: TimelineEvent[] }>(response.text);
      return parsed?.events || [];
  } catch(error) {
      console.error("Failed to extract timeline events:", error);
      return [];
  }
};

const identifyJudges = async (summary: string): Promise<JudgeSummary[]> => {
  const truncatedSummary = summary.length > 50000 ? summary.substring(0, 50000) + "...(truncated)" : summary;
  const prompt = `From the following legal summary, identify and list any judges mentioned. Return only their full names.\n\nSummary:\n${truncatedSummary}`;
  try {
      const response: GenerateContentResponse = await ai.models.generateContent({
          model: 'gemini-2.5-flash',
          contents: prompt,
          config: {
              responseMimeType: "application/json",
              responseSchema: {
                  type: Type.OBJECT,
                  properties: {
                      judges: {
                          type: Type.ARRAY,
                          description: 'A list of judge names identified in the summary.',
                          items: {
                              type: Type.OBJECT,
                              properties: {
                                  name: { type: Type.STRING, description: 'The full name of the judge.' }
                              },
                              required: ['name']
                          }
                      }
                  }
              }
          }
      });
      const parsed = safeParseJSON<{ judges: JudgeSummary[] }>(response.text);
      const rawJudges: JudgeSummary[] = parsed?.judges || [];
      const uniqueJudges = Array.from(new Set(rawJudges.map(j => j.name)))
                                .map(name => ({ name }));
      return uniqueJudges;
  } catch(error) {
      console.error("Failed to identify judges:", error);
      return [];
  }
};

export const getJudgeDetails = async (judgeName: string): Promise<JudgeDetail> => {
  const prompt = `You are an elite legal strategist. Research judge "${judgeName}" from the Denver Court System. 
  Your goal is to provide an "unfair advantage" by detailing their specific judicial tendencies, patterns in rulings, notable past cases (with outcomes and dates), and any relevant statistics (e.g., conviction rates if applicable, average sentence length, caseload type).

  CRITICAL DATA REQUESTS:
  1. **Ruling Patterns by Case Type:** Specifically look for win/loss ratios or outcome percentages for specific case types (e.g., "Civil: 60% Plaintiff Verdicts", "Criminal: 85% Conviction Rate").
  2. **Sentencing Averages:** If available, provide average sentencing lengths for common offenses (e.g., "DUI: 30 days suspended", "Assault: 2 years probation").
  3. **Disposition Time:** Average time to disposition.
  4. **Strategic Insights:** Specific advice for lawyers appearing before this judge.

  Prioritize information from official court records, legal journals, and reputable legal news sources.
  If no specific data is found for a category, state "Not available" for that category.`;

  try {
      const response: GenerateContentResponse = await ai.models.generateContent({
          model: 'gemini-3-pro-preview', // Use a powerful model for deep research
          contents: prompt,
          config: {
              tools: [{googleSearch: {}}], // Use Google Search for up-to-date information
              thinkingConfig: {
                  thinkingBudget: 32768, // Max budget for deep reasoning
              },
              responseMimeType: "application/json",
              responseSchema: {
                  type: Type.OBJECT,
                  properties: {
                      name: { type: Type.STRING, description: 'The full name of the judge.' },
                      tendencies: { type: Type.STRING, description: 'Detailed description of the judge\'s known judicial tendencies, biases, or preferred legal interpretations.' },
                      notableCases: {
                          type: Type.ARRAY,
                          description: 'A list of 3-5 notable past cases, including their names, outcomes, and approximate dates.',
                          items: {
                              type: Type.OBJECT,
                              properties: {
                                  caseName: { type: Type.STRING },
                                  outcome: { type: Type.STRING },
                                  date: { type: Type.STRING }
                              },
                              required: ['caseName', 'outcome', 'date']
                          }
                      },
                      statistics: {
                          type: Type.ARRAY,
                          description: 'Key statistics like total cases, conviction rate, average sentence, or caseload type, if available.',
                          items: {
                            type: Type.OBJECT,
                            properties: {
                              totalCases: { type: Type.NUMBER, description: 'Total number of cases handled.' },
                              convictionRate: { type: Type.STRING, description: 'Conviction rate (e.g., "75%").' },
                              averageSentence: { type: Type.STRING, description: 'Average sentence length (e.g., "2.5 years").' },
                              caseLoad: { type: Type.STRING, description: 'Type of caseload (e.g., "heavy", "moderate", "civil", "criminal").' },
                            },
                          }
                      },
                      rulingPatternsByCaseType: {
                          type: Type.ARRAY,
                          description: 'Detailed patterns of rulings broken down by different case types (e.g., criminal, civil, family), including any associated win/loss ratios or outcome percentages.',
                          items: {
                              type: Type.OBJECT,
                              properties: {
                                  caseType: { type: Type.STRING, description: 'The type of case (e.g., "Criminal", "Civil", "Family").' },
                                  pattern: { type: Type.STRING, description: 'Description of the judge\'s ruling pattern in this case type (e.g., "Generally pro-prosecution", "Often favors plaintiffs").' },
                                  percentage: { type: Type.STRING, description: 'Optional: A percentage or ratio indicating a bias or outcome frequency (e.g., "70% pro-prosecution", "60% Plaintiff Verdicts").' }
                              },
                              required: ['caseType', 'pattern']
                          }
                      },
                      averageTimeToDisposition: { type: Type.STRING, description: 'The average time it takes for cases to reach final disposition under this judge (e.g., "180 days", "6 months", "1.5 years").' },
                      sentencingData: {
                        type: Type.ARRAY,
                        description: 'Average sentencing lengths for specific offenses.',
                        items: {
                          type: Type.OBJECT,
                          properties: {
                            offense: { type: Type.STRING, description: 'The specific offense (e.g., "DUI", "Assault", "Theft").' },
                            averageSentence: { type: Type.STRING, description: 'The average sentence or typical outcome (e.g., "30 days jail", "2 years probation").' }
                          },
                          required: ['offense', 'averageSentence']
                        }
                      },
                      strategicInsights: { type: Type.STRING, description: 'Specific strategic advice for lawyers appearing before this judge, offering an "unfair advantage".' },
                  },
                  required: ['name', 'tendencies', 'notableCases', 'strategicInsights']
              }
          },
          safetySettings: [
            { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_NONE },
            { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_NONE },
            { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_NONE },
            { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_NONE },
          ],
      });

      const parsed = safeParseJSON<JudgeDetail>(response.text);
      if (!parsed) throw new Error("API returned malformed JSON for judge details.");

      return {
        name: parsed.name || judgeName,
        tendencies: parsed.tendencies || "Not available.",
        notableCases: parsed.notableCases || [],
        statistics: parsed.statistics || [],
        rulingPatternsByCaseType: parsed.rulingPatternsByCaseType || [],
        averageTimeToDisposition: parsed.averageTimeToDisposition || "Not available.",
        sentencingData: parsed.sentencingData || [],
        strategicInsights: parsed.strategicInsights || "Not available.",
      } as JudgeDetail;

  } catch (error) {
      console.error(`Failed to get details for judge ${judgeName}:`, error);
      throw new Error(`Could not retrieve deep insights for Judge ${judgeName}.`);
  }
};

export const analyzeDocument = async (
    base64Content: string, 
    mimeType: string, 
    fileName: string
): Promise<DocumentAnalysisResult> => {
    const prompt = `You are an expert legal analyst specializing in the Denver Court System. Your task is to analyze the provided document and extract strategic insights that would give a legal professional an "unfair advantage."

    Focus on:
    1.  **Strategic Summary:** A concise overview highlighting the document's legal implications and most critical points.
    2.  **Key Arguments/Positions:** Identify the main legal arguments, claims, or positions presented by relevant parties.
    3.  **Identified Entities:** Extract specific names of judges, parties involved, relevant dates, and case numbers.
    4.  **Actionable Insights:** Provide specific advice or next steps derived from the document's content, focusing on procedural advantages, potential weaknesses, or strategic opportunities within the Denver court context.

    Return the analysis in a structured JSON format.`;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview', // Use Pro for deep document analysis
            contents: {
                role: 'user',
                parts: [
                    { text: prompt },
                    { inlineData: { data: base64Content, mimeType: mimeType } }
                ]
            },
            config: {
                thinkingConfig: {
                    thinkingBudget: 32768, // Max budget for deep reasoning
                },
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        strategicSummary: { type: Type.STRING, description: 'A strategic overview of the document.' },
                        keyArguments: {
                            type: Type.ARRAY,
                            description: 'A list of main legal arguments or positions identified.',
                            items: { type: Type.STRING }
                        },
                        identifiedEntities: {
                            type: Type.ARRAY,
                            description: 'Key entities like judges, parties, dates, case numbers.',
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    type: { type: Type.STRING, enum: ['judge', 'party', 'date', 'case_number', 'other'] },
                                    value: { type: Type.STRING }
                                },
                                required: ['type', 'value']
                            }
                        },
                        actionableInsights: {
                            type: Type.ARRAY,
                            description: 'Specific advice or next steps for a legal professional.',
                            items: { type: Type.STRING }
                        },
                    },
                    required: ['strategicSummary', 'keyArguments', 'identifiedEntities', 'actionableInsights']
                }
            },
            safetySettings: [
                { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_NONE },
                { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_NONE },
                { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_NONE },
                { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_NONE },
            ],
        });

        const parsed = safeParseJSON<DocumentAnalysisResult>(response.text);
        if (!parsed) throw new Error("API returned malformed JSON for document analysis.");

        return {
            fileName,
            strategicSummary: parsed.strategicSummary,
            keyArguments: parsed.keyArguments,
            identifiedEntities: parsed.identifiedEntities,
            actionableInsights: parsed.actionableInsights,
        } as DocumentAnalysisResult;

    } catch (error) {
        console.error(`Failed to analyze document ${fileName}:`, error);
        throw new Error(`Could not retrieve deep insights for document ${fileName}.`);
    }
};

export const askDocumentQuestion = async (
    analysisResult: DocumentAnalysisResult,
    question: string
): Promise<string> => {
    // Construct a context-rich prompt
    const context = JSON.stringify(analysisResult, null, 2);

    const prompt = `You are an expert legal assistant for the Denver Court System.

    A user has uploaded a document which has been analyzed as follows:
    ${context}

    The user is now asking the following question or providing the following correction/context:
    "${question}"

    Instructions:
    1. Answer the question specifically based on the document analysis provided.
    2. If the user is correcting the analysis, acknowledge the correction and explain how it shifts the legal strategy.
    3. Cite specific Colorado/Denver laws or procedural rules if relevant to the user's query.
    4. Keep the tone professional, strategic, and concise.

    Provide the response in Markdown format.`;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                thinkingConfig: { thinkingBudget: 8192 }, // Moderate thinking budget for Q&A
            },
            safetySettings: [
                { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_NONE },
                { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_NONE },
                { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_NONE },
                { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_NONE },
            ],
        });

        const answer = response.text;
        if (!answer) throw new Error("No response generated.");
        return answer;

    } catch (error) {
        console.error("Failed to answer document question:", error);
        throw new Error("Unable to generate a response for your question.");
    }
};

export const crossReferenceDocuments = async (
    fileABase64: string,
    fileAMime: string,
    fileAName: string,
    fileBBase64: string,
    fileBMime: string,
    fileBName: string
): Promise<CrossReferenceResult> => {
    const prompt = `You are a ruthless defense attorney and evidence auditor. Your task is to perform a cross-examination of two pieces of evidence (Document A and Document B).

    Document A Name: "${fileAName}"
    Document B Name: "${fileBName}"

    YOUR MISSION: Detect "lies", contradictions, discrepancies, and factual errors between these two documents. Be extremely critical.

    Output a structured report that:
    1.  Calculates an "Overall Credibility Score" (0-100) representing how well the stories match.
    2.  Provides a brutal summary of the discrepancies.
    3.  Lists every contradiction found. For each, you must cite the claim from Document A, the conflicting claim from Document B, explain the lie, and rate the severity (High/Medium/Low).
        - HIGH SEVERITY: Directly contradicts a material fact (e.g., "Injury=Yes" vs "Injury=No").
        - MEDIUM SEVERITY: Inconsistent details (e.g., "Red car" vs "Blue car").
        - LOW SEVERITY: Minor omissions or timing differences.`;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: {
                role: 'user',
                parts: [
                    { text: `Here is Document A (${fileAName}):` },
                    { inlineData: { data: fileABase64, mimeType: fileAMime } },
                    { text: `Here is Document B (${fileBName}):` },
                    { inlineData: { data: fileBBase64, mimeType: fileBMime } },
                    { text: prompt }
                ]
            },
            config: {
                thinkingConfig: { thinkingBudget: 32768 },
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        overallCredibilityScore: { type: Type.NUMBER, description: '0-100 score. 100 = perfect match, 0 = complete fabrication.' },
                        summaryOfDiscrepancies: { type: Type.STRING, description: 'A concise, hard-hitting summary of why the documents do not align.' },
                        contradictions: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    topic: { type: Type.STRING, description: 'The subject of the lie (e.g., "Suspect Injury", "Time of Arrival").' },
                                    severity: { type: Type.STRING, enum: ['high', 'medium', 'low'] },
                                    sourceAClaim: { type: Type.STRING, description: 'What Document A stated.' },
                                    sourceBClaim: { type: Type.STRING, description: 'What Document B stated.' },
                                    analysis: { type: Type.STRING, description: 'Why this is a problem.' }
                                },
                                required: ['topic', 'severity', 'sourceAClaim', 'sourceBClaim', 'analysis']
                            }
                        }
                    },
                    required: ['overallCredibilityScore', 'summaryOfDiscrepancies', 'contradictions']
                }
            },
            safetySettings: [
                { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_NONE },
                { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_NONE },
                { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_NONE },
                { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_NONE },
            ],
        });

        const parsed = safeParseJSON<any>(response.text);
        if (!parsed) throw new Error("API returned malformed JSON for cross-reference.");

        return {
            fileAName,
            fileBName,
            overallCredibilityScore: parsed.overallCredibilityScore,
            summaryOfDiscrepancies: parsed.summaryOfDiscrepancies,
            contradictions: parsed.contradictions
        };

    } catch (error) {
        console.error("Failed to cross-reference documents:", error);
        throw new Error("Cross-examination failed. Ensure both files are valid PDFs.");
    }
};

export const generateSpeech = async (text: string): Promise<string> => {
    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName: 'Kore' }, // 'Kore' is typically a female-sounding voice
                    },
                },
            },
        });

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (!base64Audio) throw new Error("No audio data returned from TTS service.");

        return base64Audio;
    } catch (error) {
        console.error("Failed to generate speech:", error);
        throw new Error("Failed to generate audio.");
    }
};

export const searchWebWithGemini = async (
    params: SearchParams,
    onUpdate: (partialResult: PartialSearchResult) => void
): Promise<SearchResult> => {
  const prompt = buildPrompt(params);

  try {
    // onUpdate({ isSummaryStreaming: true }); // App.tsx now handles initial setting to true

    const stream = await ai.models.generateContentStream({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        tools: [{googleSearch: {}}],
        thinkingConfig: {
            thinkingBudget: 32768, // Max budget for deep reasoning
        },
        safetySettings: [
          // FIX: Corrected typo from HarmBlockBlockThreshold to HarmBlockThreshold
          { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_NONE },
          { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_NONE },
          { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_NONE },
          { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_NONE },
        ],
      }
    });

    let summary = "";
    let sources: Source[] = [];
    const sourceUris = new Set<string>();
    let lastFinishReason: string | undefined;

    for await (const chunk of stream) {
      // Robustly handle text extraction. The getter might throw if the candidate is missing or blocked.
      let chunkText = "";
      try {
        chunkText = chunk.text || "";
      } catch (e) {
        // Only log if it's not a standard "no text in this chunk" situation (which is common for thinking chunks)
        // console.warn("Information: Chunk had no text content (possibly thinking or tool usage).");
      }

      if (chunkText) {
        summary += chunkText;
      }

      // Capture finish reason if available
      if (chunk.candidates?.[0]?.finishReason) {
        lastFinishReason = chunk.candidates[0].finishReason;
      }

      const groundingChunks = chunk.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (groundingChunks) {
        const newSources: Source[] = groundingChunks
          .map((c: any) => ({
            title: c.web?.title || 'Unknown Source',
            uri: c.web?.uri || '#',
          }))
          .filter((s: Source) => s.uri !== '#' && !sourceUris.has(s.uri));

        if (newSources.length > 0) {
            newSources.forEach(s => sourceUris.add(s.uri));
            sources.push(...newSources);
        }
      }

      // Update summary and sources, keeping summary streaming true
      onUpdate({ summary: summary, sources: [...sources] });
    }

    // Summary stream finished
    onUpdate({ 
        isSummaryStreaming: false, 
        isFollowUpQuestionsLoading: true, 
        isRelatedQueriesLoading: true, 
        isTimelineLoading: true,
        isIdentifiedJudgesLoading: true, // Start loading identified judges
    });

    const finalSummary = summary.trim();

    if (!finalSummary) {
      const reasonMsg = lastFinishReason ? ` Finish Reason: ${lastFinishReason}.` : "";
      throw new Error(`The API returned an empty summary.${reasonMsg} The query may have been blocked by safety filters or yielded no search results.`);
    }

    // Parallelize follow-up generation, timeline extraction, and judge identification
    const [followUpQuestions, relatedQueries, timelineEvents, identifiedJudges] = await Promise.all([
        generateFollowUpQuestions(params.query, finalSummary),
        generateRelatedQueries(params.query),
        extractTimelineEvents(finalSummary),
        identifyJudges(finalSummary), // Add this
    ]);

    // All done loading, update with final results and set loading flags to false
    // The final result passed to setOutput in App.tsx will override these anyway
    // but this ensures the onUpdate callback has the correct final state
    onUpdate({
        followUpQuestions,
        relatedQueries,
        timelineEvents,
        identifiedJudges, // Add this
        isFollowUpQuestionsLoading: false,
        isRelatedQueriesLoading: false,
        isTimelineLoading: false,
        isIdentifiedJudgesLoading: false, // Set to false when done
    });

    const finalResult: SearchResult = {
        summary: finalSummary,
        sources,
        followUpQuestions,
        relatedQueries,
        timelineEvents,
        identifiedJudges, // Add this
        isSummaryStreaming: false, // Ensure final object reflects non-loading states
        isFollowUpQuestionsLoading: false,
        isRelatedQueriesLoading: false,
        isTimelineLoading: false,
        isIdentifiedJudgesLoading: false, // Ensure final object reflects non-loading states
    };

    return finalResult;

  } catch (error) {
    console.error("Gemini API call failed:", error);
    // On error, send an update to reset all granular loading states
    onUpdate({
        summary: "", sources: [], followUpQuestions: [], relatedQueries: [], timelineEvents: [], identifiedJudges: [],
        isSummaryStreaming: false,
        isFollowUpQuestionsLoading: false,
        isRelatedQueriesLoading: false,
        isTimelineLoading: false,
        isIdentifiedJudgesLoading: false, // Reset on error
    });
    if (error instanceof Error) {
        throw new Error(`Failed to get response from AI: ${error.message}`);
    }
    throw new Error("An unexpected error occurred while contacting the AI service.");
  }
};

