const safeParseJSON = <T>(text: string | undefined): T | null => {
    if (!text) return null;

    // Remove markdown code blocks if present (e.g., ```json ... ```)
    let cleaned = text.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();

    // Attempt to locate the JSON object/array if there's preamble text
    const firstBrace = cleaned.indexOf('{');
    const firstBracket = cleaned.indexOf('[');

    let start = -1;
    // Determine which starts first
    if (firstBrace !== -1 && firstBracket !== -1) {
        start = Math.min(firstBrace, firstBracket);
    } else if (firstBrace !== -1) {
        start = firstBrace;
    } else if (firstBracket !== -1) {
        start = firstBracket;
    }

    if (start !== -1) {
        cleaned = cleaned.substring(start);
    }

    // Attempt to trim trailing characters after the valid JSON end
    const lastBrace = cleaned.lastIndexOf('}');
    const lastBracket = cleaned.lastIndexOf(']');

    let end = -1;
    if (lastBrace !== -1 && lastBracket !== -1) {
        end = Math.max(lastBrace, lastBracket);
    } else if (lastBrace !== -1) {
        end = lastBrace;
    } else if (lastBracket !== -1) {
        end = lastBracket;
    }

    if (end !== -1) {
        cleaned = cleaned.substring(0, end + 1);
    }

    try {
        return JSON.parse(cleaned) as T;
    } catch (e) {
        console.warn("JSON Parse Failed. Attempted to parse:", cleaned.substring(0, 200) + "...");
        return null;
    }
};

const buildPrompt = (params: SearchParams): string => {
  const { query, searchType, listCount, dateRange, siteRestrict, fileType, partyName, caseNumber, caseStatus, caseType, jurisdiction } = params;

  let enhancedQuery = query;
  if (partyName?.trim()) {
    enhancedQuery += ` involving party "${partyName.trim()}"`;
  }
  if (caseNumber?.trim()) {
    enhancedQuery += ` with case number "${caseNumber.trim()}"`;
  }
  if (siteRestrict?.trim()) {
    enhancedQuery += ` site:${siteRestrict.trim()}`;
  }
  if (fileType?.trim()) {
    enhancedQuery += ` filetype:${fileType.trim()}`;
  }

  let prompt = `You are an elite legal strategist and researcher for the Denver Court System (Denver, Colorado). 

  YOUR MISSION: Do not provide basic, surface-level summaries. Your goal is to give the user an "unfair advantage" by uncovering obscure details, specific judge idiosyncrasies, hidden procedural rules, and strategic nuances that a standard search would miss.

  CRITICAL REQUIREMENT: 
  1.  **Deep Dive:** Look for the "unwritten rules" or specific standing orders of judges.
  2.  **Official Sources:** Prioritize finding and citing direct PDF links (e.g., operations manuals, court forms, rulings, dockets) from denvergov.org, courts.state.co.us, or opencities.com.
  3.  **Synthesize:** Connect the dots between local rules and actual court behavior.

  Perform a real-time web search and provide a deep, strategic analysis for: "${enhancedQuery}".`;

  if (listCount && listCount > 0) {
    prompt += ` If applicable, structure the key findings into a numbered list of ${listCount} items.`;
  }

  const dateRangePhrases: Partial<Record<DateRange, string>> = {
    [DateRange.DAY]: " Focus strictly on developments from the past 24 hours.",
    [DateRange.WEEK]: " Focus on developments from the past week.",
    [DateRange.MONTH]: " Focus on developments from the past month.",
    [DateRange.YEAR]: " Focus on developments from the past year.",
  };

  if (dateRange && dateRange !== DateRange.ANY && dateRangePhrases[dateRange]) {
      prompt += dateRangePhrases[dateRange];
  }

  if (caseStatus && caseStatus !== CaseStatus.ALL) {
      if (caseStatus === CaseStatus.OPEN) {
          prompt += " Focus specifically on active, open, or pending cases.";
      } else if (caseStatus === CaseStatus.CLOSED) {
          prompt += " Focus specifically on closed, resolved, or archived cases.";
      }
  }

  if (caseType && caseType !== CaseType.ALL) {
    prompt += ` Focus specifically on ${caseType} cases.`;
  }

  if (jurisdiction && jurisdiction !== Jurisdiction.ALL) {
    const jurisdictionMap: Record<string, string> = {
        'denver_district': 'Denver District Court',
        'denver_county': 'Denver County Court',
        'colorado_supreme': 'Colorado Supreme Court',
        'colorado_appeals': 'Colorado Court of Appeals',
    };
    const jurisdictionName = jurisdictionMap[jurisdiction] || jurisdiction;
    prompt += ` Limit scope to ${jurisdictionName}.`;
  }

  switch (searchType) {
    case SearchType.NEWS:
      prompt += " focus on the under-reported legal news and internal court updates.";
      break;
    case SearchType.ACADEMIC:
      prompt += " focus on obscure statutes, specific local rule subsections, and formal legal documentation.";
      break;
    case SearchType.SEARCH:
    default:
      prompt += " Synthesize information from dockets, legal directories, and official court announcements to find the edge.";
      break;
  }

  prompt += "\n\nPresent the analysis clearly. Do not include the URLs in the text itself; they will be extracted and listed separately."

  return prompt;
};

const generateFollowUpQuestions = async (query: string, summary: string): Promise<string[]> => {
    // Truncate summary to avoid excessive token usage if it's extremely large, ensuring JSON integrity isn't compromised by context overload
    const truncatedSummary = summary.length > 50000 ? summary.substring(0, 50000) + "...(truncated)" : summary;

    // We keep the lighter model for these helper functions to ensure UI responsiveness while the main model thinks deep.
    const prompt = `Based on the deep legal analysis of "${query}" for Denver Courts, generate 3 highly specific, strategic follow-up questions. Avoid generic questions. Ask about specific motions, judge's history on similar issues, or particular local forms.\n\nSummary Context:\n${truncatedSummary}`;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                  type: Type.OBJECT,
                  properties: {
                    questions: {
                      type: Type.ARRAY,
                      description: 'A list of 3 strategic follow-up questions.',
                      items: {
                        type: Type.STRING
                      }
                    }
                  }
                }
            }
        });
        const parsed = safeParseJSON<{ questions: string[] }>(response.text);
        return parsed?.questions || [];
    } catch(error) {
        console.error("Failed to generate follow-up questions:", error);
        return [];
    }
}

