export const searchWebWithGemini = async (
    params: SearchParams,
    onUpdate: (partialResult: PartialSearchResult) => void
): Promise<SearchResult> => {
  const prompt = buildPrompt(params);

  try {
    // onUpdate({ isSummaryStreaming: true }); // App.tsx now handles initial setting to true

    const stream = await ai.models.generateContentStream({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        tools: [{googleSearch: {}}],
        thinkingConfig: {
            thinkingBudget: 32768, // Max budget for deep reasoning
        },
        safetySettings: [
          // FIX: Corrected typo from HarmBlockBlockThreshold to HarmBlockThreshold
          { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_NONE },
          { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_NONE },
          { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_NONE },
          { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_NONE },
        ],
      }
    });

    let summary = "";
    let sources: Source[] = [];
    const sourceUris = new Set<string>();
    let lastFinishReason: string | undefined;

    for await (const chunk of stream) {
      // Robustly handle text extraction. The getter might throw if the candidate is missing or blocked.
      let chunkText = "";
      try {
        chunkText = chunk.text || "";
      } catch (e) {
        // Only log if it's not a standard "no text in this chunk" situation (which is common for thinking chunks)
        // console.warn("Information: Chunk had no text content (possibly thinking or tool usage).");
      }

      if (chunkText) {
        summary += chunkText;
      }

      // Capture finish reason if available
      if (chunk.candidates?.[0]?.finishReason) {
        lastFinishReason = chunk.candidates[0].finishReason;
      }

      const groundingChunks = chunk.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (groundingChunks) {
        const newSources: Source[] = groundingChunks
          .map((c: any) => ({
            title: c.web?.title || 'Unknown Source',
            uri: c.web?.uri || '#',
          }))
          .filter((s: Source) => s.uri !== '#' && !sourceUris.has(s.uri));

        if (newSources.length > 0) {
            newSources.forEach(s => sourceUris.add(s.uri));
            sources.push(...newSources);
        }
      }

      // Update summary and sources, keeping summary streaming true
      onUpdate({ summary: summary, sources: [...sources] });
    }

    // Summary stream finished
    onUpdate({ 
        isSummaryStreaming: false, 
        isFollowUpQuestionsLoading: true, 
        isRelatedQueriesLoading: true, 
        isTimelineLoading: true,
        isIdentifiedJudgesLoading: true, // Start loading identified judges
    });

    const finalSummary = summary.trim();

    if (!finalSummary) {
      const reasonMsg = lastFinishReason ? ` Finish Reason: ${lastFinishReason}.` : "";
      throw new Error(`The API returned an empty summary.${reasonMsg} The query may have been blocked by safety filters or yielded no search results.`);
    }

    // Parallelize follow-up generation, timeline extraction, and judge identification
    const [followUpQuestions, relatedQueries, timelineEvents, identifiedJudges] = await Promise.all([
        generateFollowUpQuestions(params.query, finalSummary),
        generateRelatedQueries(params.query),
        extractTimelineEvents(finalSummary),
        identifyJudges(finalSummary), // Add this
    ]);

    // All done loading, update with final results and set loading flags to false
    // The final result passed to setOutput in App.tsx will override these anyway
    // but this ensures the onUpdate callback has the correct final state
    onUpdate({
        followUpQuestions,
        relatedQueries,
        timelineEvents,
        identifiedJudges, // Add this
        isFollowUpQuestionsLoading: false,
        isRelatedQueriesLoading: false,
        isTimelineLoading: false,
        isIdentifiedJudgesLoading: false, // Set to false when done
    });

    const finalResult: SearchResult = {
        summary: finalSummary,
        sources,
        followUpQuestions,
        relatedQueries,
        timelineEvents,
        identifiedJudges, // Add this
        isSummaryStreaming: false, // Ensure final object reflects non-loading states
        isFollowUpQuestionsLoading: false,
        isRelatedQueriesLoading: false,
        isTimelineLoading: false,
        isIdentifiedJudgesLoading: false, // Ensure final object reflects non-loading states
    };

    return finalResult;

  } catch (error) {
    console.error("Gemini API call failed:", error);
    // On error, send an update to reset all granular loading states
    onUpdate({
        summary: "", sources: [], followUpQuestions: [], relatedQueries: [], timelineEvents: [], identifiedJudges: [],
        isSummaryStreaming: false,
        isFollowUpQuestionsLoading: false,
        isRelatedQueriesLoading: false,
        isTimelineLoading: false,
        isIdentifiedJudgesLoading: false, // Reset on error
    });
    if (error instanceof Error) {
        throw new Error(`Failed to get response from AI: ${error.message}`);
    }
    throw new Error("An unexpected error occurred while contacting the AI service.");
  }
};

