                    </div>

                    <div className="flex-grow p-6 overflow-y-auto">
                        {selectedNode ? (
                            <div className="animate-[fadeIn_0.2s_ease-out]">
                                <div className="flex items-center gap-3 mb-4">
                                    <div className={`p-3 rounded-lg ${getNodeColor(selectedNode.type, false).replace('text-white', '')} bg-opacity-20`}>
                                        {getNodeIcon(selectedNode.type, "w-8 h-8 text-white")}
                                    </div>
                                    <div>
                                        <h4 className="text-xl font-bold text-slate-100">{selectedNode.label}</h4>
                                        <span className="text-xs uppercase font-bold text-slate-500 tracking-wider">{selectedNode.type}</span>
                                    </div>
                                </div>

                                {selectedNode.bradyFlag && (
                                    <div className="bg-red-900/30 border border-red-500/50 rounded-lg p-4 mb-4 flex items-start gap-3">
                                        <AlertIcon className="w-5 h-5 text-red-400 flex-shrink-0 mt-0.5" />
                                        <div>
                                            <p className="text-sm font-bold text-red-300">Brady / Credibility Flag</p>
                                            <p className="text-xs text-red-200/80 mt-1">{selectedNode.bradyFlag}</p>
                                        </div>
                                    </div>
                                )}

                                <div className="space-y-4">
                                    <div>
                                        <h5 className="text-sm font-bold text-slate-400 uppercase mb-1">Description</h5>
                                        <p className="text-slate-200 text-sm">{selectedNode.description || "No description provided."}</p>
                                    </div>
                                    {selectedNode.sourceCitation && (
                                        <div>
                                            <h5 className="text-sm font-bold text-slate-400 uppercase mb-1">Source</h5>
                                            <p className="text-blue-300 text-sm italic font-mono bg-slate-900 p-2 rounded border border-slate-700">
                                                {selectedNode.sourceCitation}
                                            </p>
                                        </div>
                                    )}
                                </div>
                            </div>
                        ) : (
                            <div className="text-center text-slate-500 mt-20">
                                <BrainCircuitIcon className="w-16 h-16 mx-auto mb-4 opacity-20" />
                                <p>Select a node in the graph to view evidence details and source citations.</p>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}

import React, { useState, useCallback, useEffect } from 'react';
import { SearchType, type SearchParams, DateRange, CaseStatus, type Bookmark, type SearchBookmark, type DocumentBookmark, type CrossRefBookmark, type PartialSearchResult, type SearchResult, type DocumentAnalysisResult, type CrossReferenceResult, type NarrativeMapResult, CaseType, Jurisdiction } from './types';
import { searchWebWithGemini, analyzeDocument, crossReferenceDocuments, generateNarrativeMap } from './services/geminiService';
import { getCachedResult, setCachedResult, clearCache, generateCacheKey } from './services/cacheService';
import { addToHistory, clearHistory } from './services/historyService';
import { getBookmarks, saveBookmark, removeBookmark, isSearchBookmarked, isDocBookmarked, isCrossRefBookmarked, clearBookmarks, generateSearchKey, generateDocKey, generateCrossRefKey } from './services/bookmarkService';
import { MAX_QUERY_LENGTH, MIN_LIST_COUNT, MAX_LIST_COUNT } from './constants';
import Header from './components/Header';
import Banner from './components/Banner';
import SearchForm from './components/SearchForm';
import ResultsDisplay from './components/ResultsDisplay';
import Examples from './components/Examples';
import Bookmarks from './components/Bookmarks';
import JudgeDetailModal from './components/JudgeDetailModal';
import DocumentAnalysisModal from './components/DocumentAnalysisModal';
import CrossReferenceModal from './components/CrossReferenceModal';
import NarrativeMapper from './components/NarrativeMapper';

export default function App(): React.ReactNode {
  const [searchParams, setSearchParams] = useState<SearchParams>({
    query: '',
    searchType: SearchType.SEARCH,
    listCount: undefined,
    dateRange: DateRange.ANY,
    siteRestrict: '',
    fileType: '',
    partyName: '',
    caseNumber: '',
    caseStatus: CaseStatus.ALL,
    caseType: CaseType.ALL,
    jurisdiction: Jurisdiction.ALL,
  });
  const [currentSearchParamsForResults, setCurrentSearchParamsForResults] = useState<SearchParams | null>(null);
  const [output, setOutput] = useState<SearchResult | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false); // Overall network loading status
  const [error, setError] = useState<string | null>(null);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);

  // State for Judge Detail Modal
  const [showJudgeModal, setShowJudgeModal] = useState(false);
  const [selectedJudgeName, setSelectedJudgeName] = useState<string | null>(null);

  // State for Document Analysis Modal
  const [showDocumentAnalysisModal, setShowDocumentAnalysisModal] = useState(false);
  const [documentAnalysisResult, setDocumentAnalysisResult] = useState<DocumentAnalysisResult | null>(null);
  const [isDocumentAnalysisLoading, setIsDocumentAnalysisLoading] = useState<boolean>(false);
  const [documentAnalysisError, setDocumentAnalysisError] = useState<string | null>(null);

  // State for Cross-Reference Modal
  const [showCrossRefModal, setShowCrossRefModal] = useState(false);
  const [crossRefResult, setCrossRefResult] = useState<CrossReferenceResult | null>(null);
  const [isCrossRefLoading, setIsCrossRefLoading] = useState(false);
  const [crossRefError, setCrossRefError] = useState<string | null>(null);

  // State for Narrative Mapper
  const [showNarrativeMapper, setShowNarrativeMapper] = useState(false);

  useEffect(() => {
    setBookmarks(getBookmarks());
  }, []);

  const executeSearch = useCallback(async (params: SearchParams) => {
    const finalParams: SearchParams = { ...params, query: params.query.trim() };

    // --- Validation ---
    if (!finalParams.query) {
      setError('Search query cannot be empty.');
      return;
    }
    if (finalParams.query.length > MAX_QUERY_LENGTH) {
      setError(`Search query cannot exceed ${MAX_QUERY_LENGTH} characters.`);
      return;
    }
    const { listCount } = finalParams;
    if (listCount !== undefined && (listCount < MIN_LIST_COUNT || listCount > MAX_LIST_COUNT)) {
      setError(`List count must be between ${MIN_LIST_COUNT} and ${MAX_LIST_COUNT}.`);
      return;
    }

    // --- Check Cache ---
    const cachedResult = getCachedResult(finalParams);
    if (cachedResult) {
      setOutput({
        ...cachedResult, // Use cached data
        isSummaryStreaming: false, // Ensure loading states are false for cached results
        isFollowUpQuestionsLoading: false,
        isRelatedQueriesLoading: false,
        isTimelineLoading: false, // Ensure loading states are false for cached results
        isIdentifiedJudgesLoading: false, // Ensure loading states are false for cached results
      });
      setCurrentSearchParamsForResults(finalParams);
      setError(null);
      window.scrollTo({ top: 0, behavior: 'smooth' });
      return;
    }

    setIsLoading(true); // Start overall loading
    setError(null);
    // Initialize output with empty content and set summary streaming to true
    setOutput({
      summary: '',
      sources: [],
      followUpQuestions: [],
      relatedQueries: [],
      timelineEvents: [], // Initialize timeline events
      identifiedJudges: [], // Initialize identified judges
      isSummaryStreaming: true, // Initially assume summary will stream
      isFollowUpQuestionsLoading: false, // These will be set true later by geminiService
      isRelatedQueriesLoading: false,    // These will be set true later by geminiService
      isTimelineLoading: false, // These will be set true later by geminiService
      isIdentifiedJudgesLoading: false, // These will be set true later by geminiService
    });
    setCurrentSearchParamsForResults(finalParams);
    window.scrollTo({ top: 0, behavior: 'smooth' });

    try {
      const onUpdate = (partialResult: PartialSearchResult) => {
        setOutput(prev => {
            // If prev is null, initialize with defaults and current partialResult
            const current = prev || {
                summary: '',
                sources: [],
                followUpQuestions: [],
                relatedQueries: [],
                timelineEvents: [],
                identifiedJudges: [],
                isSummaryStreaming: false,
                isFollowUpQuestionsLoading: false,
                isRelatedQueriesLoading: false,
                isTimelineLoading: false,
                isIdentifiedJudgesLoading: false,
            };

            return {
                summary: partialResult.summary ?? current.summary,
                sources: partialResult.sources ?? current.sources,
                followUpQuestions: partialResult.followUpQuestions ?? current.followUpQuestions,
                relatedQueries: partialResult.relatedQueries ?? current.relatedQueries,
                timelineEvents: partialResult.timelineEvents ?? current.timelineEvents, // Update timeline events
                identifiedJudges: partialResult.identifiedJudges ?? current.identifiedJudges, // Update identified judges
                isSummaryStreaming: partialResult.isSummaryStreaming ?? current.isSummaryStreaming,
                isFollowUpQuestionsLoading: partialResult.isFollowUpQuestionsLoading ?? current.isFollowUpQuestionsLoading,
                isRelatedQueriesLoading: partialResult.isRelatedQueriesLoading ?? current.isRelatedQueriesLoading,
                isTimelineLoading: partialResult.isTimelineLoading ?? current.isTimelineLoading, // Update timeline loading
                isIdentifiedJudgesLoading: partialResult.isIdentifiedJudgesLoading ?? current.isIdentifiedJudgesLoading, // Update judge identification loading
            };
        });
      };

      const result = await searchWebWithGemini(finalParams, onUpdate);
      // After full result is back, ensure all loading flags are false and final content is set
      setOutput(prev => ({
          ...prev!, // Take existing state (which should have streamed parts)
          ...result, // Overwrite with final content and ensure loading flags are false
          isSummaryStreaming: false,
          isFollowUpQuestionsLoading: false,
          isRelatedQueriesLoading: false,
          isTimelineLoading: false, // Ensure false when done
          isIdentifiedJudgesLoading: false, // Ensure false when done
      }));
      setCachedResult(finalParams, result);
      addToHistory(finalParams);
    } catch (err) {
      console.error(err);
      setError(err instanceof Error ? err.message : 'An unknown error occurred. Please try again.');
      // On error, clear output and reset all granular loading states
      setOutput(null); // Clear all previous results on error
      setCurrentSearchParamsForResults(null);
    } finally {
      setIsLoading(false); // End overall loading
    }
  }, []);

  const handleSearch = useCallback(() => {
    executeSearch(searchParams);
  }, [searchParams, executeSearch]);

  const handleFollowUpSearch = useCallback((question: string) => {
    const newParams: SearchParams = {
      query: question,
      searchType: searchParams.searchType, // Keep the original search type
      listCount: undefined,
      dateRange: DateRange.ANY,
      siteRestrict: '',
      fileType: '',
      partyName: '', // Reset party name for follow-ups
      caseNumber: '', // Reset case number for follow-ups
      caseStatus: CaseStatus.ALL, // Reset case status for follow-ups
      caseType: CaseType.ALL, // Reset
      jurisdiction: Jurisdiction.ALL, // Reset
    };
    setSearchParams(newParams);
    executeSearch(newParams);
  }, [searchParams.searchType, executeSearch]);

  const handleAnalysisSearch = useCallback((analysisPrompt: string) => {
    if (!currentSearchParamsForResults?.query) return;

    const newQuery = `${analysisPrompt} for "${currentSearchParamsForResults.query}"`;
    const newParams: SearchParams = {
      query: newQuery,
      searchType: SearchType.SEARCH, // Default to general search for analysis
      listCount: undefined,
      dateRange: DateRange.ANY,
      siteRestrict: '',
      fileType: '',
      partyName: '', // Reset party name for analysis
      caseNumber: '', // Reset case number for analysis
      caseStatus: CaseStatus.ALL, // Reset case status for analysis
      caseType: CaseType.ALL,
      jurisdiction: Jurisdiction.ALL,
    };
    setSearchParams(newParams);
    executeSearch(newParams);
  }, [currentSearchParamsForResults, executeSearch]);


  const handleClearSearch = useCallback(() => {
    setSearchParams({
      query: '',
      searchType: SearchType.SEARCH,
      listCount: undefined,
      dateRange: DateRange.ANY,
      siteRestrict: '',
      fileType: '',
      partyName: '',
      caseNumber: '',
      caseStatus: CaseStatus.ALL,
      caseType: CaseType.ALL,
      jurisdiction: Jurisdiction.ALL,
    });
    setOutput(null);
    setCurrentSearchParamsForResults(null);
    setError(null);
    setShowJudgeModal(false); // Close modal on clear
    setSelectedJudgeName(null); // Clear selected judge
    setDocumentAnalysisResult(null); // Clear document analysis result
    setDocumentAnalysisError(null); // Clear document analysis error
    setShowDocumentAnalysisModal(false); // Close document analysis modal
    setCrossRefResult(null);
    setShowCrossRefModal(false);
  }, []);

  const handleClearLocalData = useCallback(() => {
    if (window.confirm('Are you sure you want to clear all cache, history, and bookmarks? This action cannot be undone.')) {
        clearCache();
        clearHistory();
        clearBookmarks();
        setBookmarks([]); // Update state
        alert('All local data has been cleared.');
    }
  }, []);

  const handleExampleSelect = useCallback((example: SearchParams) => {
    setSearchParams({
      query: example.query,
      searchType: example.searchType,
      listCount: example.listCount,
      dateRange: DateRange.ANY,
      siteRestrict: '',
      fileType: '',
      partyName: '',
      caseNumber: '',
      caseStatus: CaseStatus.ALL,
      caseType: CaseType.ALL,
      jurisdiction: Jurisdiction.ALL,
    });
  }, []);

  const handleHistorySelect = useCallback((params: SearchParams) => {
    setSearchParams(params);
    executeSearch(params);
  }, [executeSearch]);

  // --- Bookmark Handlers ---

  // 1. Search Results
  const handleSaveResult = (params: SearchParams, result: SearchResult) => {
    const key = generateSearchKey(params);
    const bookmark: SearchBookmark = {
        key, type: 'search', params, result, savedAt: Date.now()
    };
    saveBookmark(bookmark);
    setBookmarks(getBookmarks()); // Refresh bookmarks from source
  };

  const handleRemoveSave = (params: SearchParams) => {
    const key = generateSearchKey(params);
    removeBookmark(key);
    setBookmarks(getBookmarks());
  };

  // 2. Document Analysis
  const handleSaveDocument = (result: DocumentAnalysisResult) => {
      const key = generateDocKey(result.fileName);
      const bookmark: DocumentBookmark = {
          key, type: 'document_analysis', result, savedAt: Date.now()
      };
      saveBookmark(bookmark);
      setBookmarks(getBookmarks());
  };

  const handleRemoveDocumentSave = (result: DocumentAnalysisResult) => {
      const key = generateDocKey(result.fileName);
      removeBookmark(key);
      setBookmarks(getBookmarks());
  };

  // 3. Cross Reference
  const handleSaveCrossRef = (result: CrossReferenceResult) => {
      const key = generateCrossRefKey(result.fileAName, result.fileBName);
      const bookmark: CrossRefBookmark = {
          key, type: 'cross_reference', result, savedAt: Date.now()
      };
      saveBookmark(bookmark);
      setBookmarks(getBookmarks());
  };

  const handleRemoveCrossRefSave = (result: CrossReferenceResult) => {
      const key = generateCrossRefKey(result.fileAName, result.fileBName);
      removeBookmark(key);
      setBookmarks(getBookmarks());
  };

  // Generic Delete
  const handleDeleteBookmark = (key: string) => {
      removeBookmark(key);
      setBookmarks(getBookmarks());
  };

  const handleViewBookmark = (bookmark: Bookmark) => {
    if (bookmark.type === 'search') {
        setSearchParams(bookmark.params);
        setOutput({
          ...bookmark.result,
          isSummaryStreaming: false, // Ensure loading states are false for bookmarked results
          isFollowUpQuestionsLoading: false,
          isRelatedQueriesLoading: false,
          isTimelineLoading: false, // Ensure loading states are false for bookmarked results
          isIdentifiedJudgesLoading: false, // Ensure loading states are false for bookmarked results
        });
        setCurrentSearchParamsForResults(bookmark.params);
        window.scrollTo({ top: 0, behavior: 'smooth' });
    } else if (bookmark.type === 'document_analysis') {
        setDocumentAnalysisResult(bookmark.result);
        setShowDocumentAnalysisModal(true);
    } else if (bookmark.type === 'cross_reference') {
        setCrossRefResult(bookmark.result);
        setShowCrossRefModal(true);
    }
  };

  const handleSaveCurrentSearch = useCallback(() => {
      if (currentSearchParamsForResults && output) {
          handleSaveResult(currentSearchParamsForResults, output);
      }
  }, [currentSearchParamsForResults, output]);

  // --- Judge Modal Handlers ---
  const openJudgeModal = useCallback((judgeName: string) => {
    setSelectedJudgeName(judgeName);
    setShowJudgeModal(true);
  }, []);

  const closeJudgeModal = useCallback(() => {
    setShowJudgeModal(false);
    setSelectedJudgeName(null);
  }, []);

  // --- Document Analysis Handlers ---
  const openDocumentAnalysisModal = useCallback(() => {
    setShowDocumentAnalysisModal(true);
    setDocumentAnalysisResult(null); // Clear previous results when opening
    setDocumentAnalysisError(null);
  }, []);

  const closeDocumentAnalysisModal = useCallback(() => {
    setShowDocumentAnalysisModal(false);
    setDocumentAnalysisResult(null);
    setDocumentAnalysisError(null);
  }, []);

  const handleDocumentAnalysis = useCallback(async (base64Content: string, mimeType: string, fileName: string) => {
    setIsDocumentAnalysisLoading(true);
    setDocumentAnalysisError(null);
    try {
      const result = await analyzeDocument(base64Content, mimeType, fileName);
      setDocumentAnalysisResult(result);
    } catch (err) {
      console.error("Document analysis failed:", err);
      setDocumentAnalysisError(err instanceof Error ? err.message : 'An unknown error occurred during document analysis.');
    } finally {
      setIsDocumentAnalysisLoading(false);
    }
  }, []);

  // --- Cross Reference (Lie Detector) Handlers ---
  const openCrossRefModal = useCallback(() => {
    setShowCrossRefModal(true);
    setCrossRefResult(null);
    setCrossRefError(null);
  }, []);

  const closeCrossRefModal = useCallback(() => {
    setShowCrossRefModal(false);
    setCrossRefResult(null);
    setCrossRefError(null);
  }, []);

  const handleCrossReference = useCallback(async (
      fileABase64: string, fileAMime: string, fileAName: string,
      fileBBase64: string, fileBMime: string, fileBName: string
  ) => {
      setIsCrossRefLoading(true);
      setCrossRefError(null);
      try {
          const result = await crossReferenceDocuments(fileABase64, fileAMime, fileAName, fileBBase64, fileBMime, fileBName);
          setCrossRefResult(result);
      } catch (err) {
          console.error("Cross-reference failed:", err);
          setCrossRefError(err instanceof Error ? err.message : 'An unknown error occurred during cross-reference.');
      } finally {
          setIsCrossRefLoading(false);
      }
  }, []);

  // --- Narrative Mapper Handlers ---
  const handleNarrativeGeneration = useCallback(async (base64: string, mime: string, name: string): Promise<NarrativeMapResult> => {
      return await generateNarrativeMap(base64, mime, name);
  }, []);


  return (
    <div className="min-h-screen">
      <main className="max-w-4xl mx-auto p-4 sm:p-6 md:p-8">
        <div className="space-y-8">
          <Banner />
          <Header 
            onAnalyzeDocumentClick={openDocumentAnalysisModal} 
            onCrossReferenceClick={openCrossRefModal} 
            onNarrativeMapperClick={() => setShowNarrativeMapper(true)}
          />
          <div className="bg-slate-800 p-6 rounded-lg shadow-md border border-slate-700">
            <SearchForm
              params={searchParams}
              setParams={setSearchParams}
              onSearch={handleSearch}
              isLoading={isLoading}
              onClear={handleClearSearch}
              onSelectHistory={handleHistorySelect}
              onSave={handleSaveCurrentSearch}
              canSave={!!output && !!currentSearchParamsForResults}
            />
            <div className="mt-6 pt-6 border-t border-slate-700">
              <Examples onSelectExample={handleExampleSelect} />
            </div>
          </div>

          <Bookmarks 
            bookmarks={bookmarks}
            onView={handleViewBookmark}
            onDelete={handleDeleteBookmark}
          />

          {error && (
            <div className="bg-red-500/10 border border-red-500/30 text-red-300 px-4 py-3 rounded-lg relative" role="alert">
              <strong className="font-extrabold">Error: </strong>
              <span className="block sm:inline">{error}</span>
            </div>
          )}

          <ResultsDisplay
            output={output}
            searchParams={currentSearchParamsForResults}
            isLoading={isLoading} // Overall loading
            onQuestionClick={handleFollowUpSearch}
            onAnalysisClick={handleAnalysisSearch}
            onSave={handleSaveResult}
            onRemoveSave={handleRemoveSave}
            isSaved={currentSearchParamsForResults ? isSearchBookmarked(currentSearchParamsForResults) : false}
            onJudgeClick={openJudgeModal} // Pass the handler to ResultsDisplay
          />
        </div>
      </main>
      <footer className="text-center py-6 text-base font-semibold text-slate-400 space-y-2">
        <p>Powered by Gemini and React</p>
        <button
          onClick={handleClearLocalData}
          className="px-3 py-1 bg-slate-700 text-slate-300 text-sm font-semibold rounded-md hover:bg-slate-600 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-slate-900 focus:ring-slate-500 transition-colors"
          title="Clear all cached results, history, and bookmarks from your browser's local storage"
        >
          Clear All Local Data
        </button>
      </footer>
      {showJudgeModal && selectedJudgeName && (
        <JudgeDetailModal 
          judgeName={selectedJudgeName} 
          onClose={closeJudgeModal} 
        />
      )}
      {showDocumentAnalysisModal && (
        <DocumentAnalysisModal
          onClose={closeDocumentAnalysisModal}
          onAnalyze={handleDocumentAnalysis}
          result={documentAnalysisResult}
          isLoading={isDocumentAnalysisLoading}
          error={documentAnalysisError}
          onSave={handleSaveDocument}
          onRemoveSave={handleRemoveDocumentSave}
          isSaved={documentAnalysisResult ? isDocBookmarked(documentAnalysisResult.fileName) : false}
        />
      )}
      {showCrossRefModal && (
        <CrossReferenceModal
          onClose={closeCrossRefModal}
          onAnalyze={handleCrossReference}
          result={crossRefResult}
          isLoading={isCrossRefLoading}
          error={crossRefError}
          onSave={handleSaveCrossRef}
          onRemoveSave={handleRemoveCrossRefSave}
          isSaved={crossRefResult ? isCrossRefBookmarked(crossRefResult.fileAName, crossRefResult.fileBName) : false}
        />
      )}
      {showNarrativeMapper && (
        <NarrativeMapper 
          onClose={() => setShowNarrativeMapper(false)} 
          onGenerate={handleNarrativeGeneration}
        />
      )}
    </div>
  );
}

import React, { useState, useCallback, useRef, useEffect, useMemo } from 'react';
import { NarrativeMapResult, NarrativeNode, NarrativeLink } from '../types';
import SpinnerIcon from './icons/SpinnerIcon';
import CloseIcon from './icons/CloseIcon';
import BrainCircuitIcon from './icons/BrainCircuitIcon';
import UserIcon from './icons/UserIcon';
import GavelIcon from './icons/GavelIcon'; // Institutions
import GlobeIcon from './icons/GlobeIcon'; // Locations
import DocumentIcon from './icons/DocumentIcon'; // Default/Event
import AlertIcon from './icons/AlertIcon';
import CalendarIcon from './icons/CalendarIcon';

interface NarrativeMapperProps {
    onClose: () => void;
    onGenerate: (base64Content: string, mimeType: string, fileName: string) => Promise<NarrativeMapResult>;
}

const MAX_FILE_SIZE_MB = 10;

// --- Node Icons Helper ---
const getNodeIcon = (type: string, className = "w-5 h-5") => {
    switch (type) {
        case 'person': return <UserIcon className={className} />;
        case 'location': return <GlobeIcon className={className} />;
        case 'institution': return <GavelIcon className={className} />;
        case 'event': return <CalendarIcon className={className} />;
        default: return <DocumentIcon className={className} />;
    }
};

const getNodeColor = (type: string, isBrady: boolean) => {
    if (isBrady) return 'bg-red-500 border-red-300 text-white';
    switch (type) {
        case 'person': return 'bg-blue-600 border-blue-400 text-white';
        case 'location': return 'bg-green-600 border-green-400 text-white';
        case 'institution': return 'bg-slate-600 border-slate-400 text-white';
        case 'event': return 'bg-purple-600 border-purple-400 text-white';
        default: return 'bg-slate-600 border-slate-400 text-white';
    }
};

// --- Custom Graph View (SVG) ---
interface GraphViewProps {
    data: NarrativeMapResult;
    onNodeClick: (node: NarrativeNode) => void;
}

const GraphView: React.FC<GraphViewProps> = ({ data, onNodeClick }) => {
    const svgRef = useRef<SVGSVGElement>(null);
    const [positions, setPositions] = useState<Record<string, { x: number, y: number }>>({});
    const [draggingId, setDraggingId] = useState<string | null>(null);

    // Initial Layout Calculation (Simple circle/force hybrid)
    useEffect(() => {
        const width = 800;
        const height = 600;
        const newPositions: Record<string, { x: number, y: number }> = {};

        const centerX = width / 2;
        const centerY = height / 2;

        // Categorize nodes
        const people = data.nodes.filter(n => n.type === 'person');
        const others = data.nodes.filter(n => n.type !== 'person');

        // Place people in a central circle
        people.forEach((node, i) => {
            const angle = (i / people.length) * 2 * Math.PI;
            const radius = 150;
            newPositions[node.id] = {
                x: centerX + Math.cos(angle) * radius,
                y: centerY + Math.sin(angle) * radius
            };
        });

        // Place others in an outer circle
        others.forEach((node, i) => {
            const angle = (i / others.length) * 2 * Math.PI;
            const radius = 280;
            newPositions[node.id] = {
                x: centerX + Math.cos(angle) * radius,
                y: centerY + Math.sin(angle) * radius
            };
        });

        setPositions(newPositions);
    }, [data]);

    const handleMouseDown = (id: string) => setDraggingId(id);
    const handleMouseUp = () => setDraggingId(null);
    const handleMouseMove = (e: React.MouseEvent) => {
        if (!draggingId || !svgRef.current) return;
        const rect = svgRef.current.getBoundingClientRect();
        setPositions(prev => ({
            ...prev,
            [draggingId]: {
                x: e.clientX - rect.left,
                y: e.clientY - rect.top
            }
        }));
    };

    return (
        <div className="bg-slate-900 rounded-lg border border-slate-700 overflow-hidden relative" style={{ height: '600px' }}>
            <svg 
                ref={svgRef}
                width="100%" 
                height="100%" 
                viewBox="0 0 800 600"
                onMouseMove={handleMouseMove}
                onMouseUp={handleMouseUp}
                onMouseLeave={handleMouseUp}
                className="cursor-move"
            >
                <defs>
                    <marker id="arrow-explicit" markerWidth="10" markerHeight="7" refX="29" refY="3.5" orient="auto">
                        <polygon points="0 0, 10 3.5, 0 7" fill="#94a3b8" />
                    </marker>
                    <marker id="arrow-inferred" markerWidth="10" markerHeight="7" refX="29" refY="3.5" orient="auto">
                        <polygon points="0 0, 10 3.5, 0 7" fill="#94a3b8" />
                    </marker>
                     <marker id="arrow-contradiction" markerWidth="10" markerHeight="7" refX="29" refY="3.5" orient="auto">
                        <polygon points="0 0, 10 3.5, 0 7" fill="#ef4444" />
                    </marker>
                </defs>

                {/* Links */}
                {data.links.map((link, i) => {
                    const start = positions[link.source];
                    const end = positions[link.target];
                    if (!start || !end) return null;

                    const type = link.type?.toLowerCase() || 'explicit';
                    let strokeColor = '#94a3b8'; // slate-400
                    let strokeDash = '0';
                    let strokeWidth = '2';
                    let markerEnd = 'url(#arrow-explicit)';

                    if (type === 'inferred') {
                        strokeDash = '5,5';
                        markerEnd = 'url(#arrow-inferred)';
                    } else if (type === 'contradiction') {
                        strokeColor = '#ef4444'; // red-500
                        strokeWidth = '3';
                        markerEnd = 'url(#arrow-contradiction)';
                    }

                    return (
                        <g key={i}>
                            <line 
                                x1={start.x} y1={start.y} 
                                x2={end.x} y2={end.y} 
                                stroke={strokeColor} 
                                strokeWidth={strokeWidth} 
                                strokeDasharray={strokeDash}
                                markerEnd={markerEnd}
                                opacity="0.8"
                            />
                            {/* Link Label (midpoint) */}
                            <text 
                                x={(start.x + end.x) / 2} 
                                y={(start.y + end.y) / 2 - 5} 
                                fill={type === 'contradiction' ? '#fca5a5' : '#cbd5e1'}
                                fontSize="11" 
                                textAnchor="middle" 
                                className="bg-slate-900/80 px-1 rounded font-mono"
                                style={{ textShadow: '0 1px 2px rgba(0,0,0,0.8)' }}
                            >
                                {link.label}
                            </text>
                        </g>
                    );
                })}

                {/* Nodes */}
                {data.nodes.map((node) => {
                    const pos = positions[node.id];
                    if (!pos) return null;
                    const colorClass = getNodeColor(node.type, !!node.bradyFlag);
                    // Parse tailwind classes to raw colors for SVG
                    const fill = !!node.bradyFlag ? '#ef4444' : (node.type === 'person' ? '#2563eb' : '#475569');

                    return (
                        <g 
                            key={node.id} 
                            transform={`translate(${pos.x}, ${pos.y})`}
                            onMouseDown={() => handleMouseDown(node.id)}
                            onClick={() => onNodeClick(node)}
                            className="cursor-pointer hover:opacity-90 transition-opacity"
                        >
                            <circle r="25" fill={fill} stroke="#fff" strokeWidth="2.5" className="shadow-lg" />
                            {node.bradyFlag && (
                                <text x="18" y="-18" fontSize="16">⚠️</text>
                            )}
                            <foreignObject x="-12" y="-12" width="24" height="24">
                                <div className="text-white flex justify-center drop-shadow-md">
                                    {getNodeIcon(node.type, "w-6 h-6")}
                                </div>
                            </foreignObject>
                            <text y="42" fill="#fff" fontSize="12" textAnchor="middle" fontWeight="bold" style={{ textShadow: '0 1px 3px rgba(0,0,0,1)' }}>
                                {node.label}
                            </text>
                        </g>
                    );
                })}
            </svg>

            {/* Improved Legend */}
            <div className="absolute bottom-4 left-4 bg-slate-800/90 p-4 rounded-lg border border-slate-600 shadow-lg backdrop-blur-sm text-xs text-slate-300 pointer-events-none select-none z-10">
                <h5 className="font-bold text-slate-100 mb-2 border-b border-slate-600 pb-1">Legend</h5>

                <div className="space-y-2">
                    <div className="flex items-center gap-2">
                        <div className="w-3 h-3 bg-blue-600 rounded-full border border-blue-400"></div> Person
                    </div>
                    <div className="flex items-center gap-2">
                         <div className="w-3 h-3 bg-green-600 rounded-full border border-green-400"></div> Location
                    </div>
                    <div className="flex items-center gap-2">
                         <div className="w-3 h-3 bg-slate-600 rounded-full border border-slate-400"></div> Institution/Asset
                    </div>
                    <div className="flex items-center gap-2">
                         <div className="w-3 h-3 bg-purple-600 rounded-full border border-purple-400"></div> Event
                    </div>
                    <div className="flex items-center gap-2">
                         <div className="w-3 h-3 bg-red-500 rounded-full border border-red-300"></div> Brady Flag
                    </div>
                </div>

                <div className="mt-3 pt-2 border-t border-slate-600 space-y-2">
                    <div className="flex items-center gap-2">
                        <svg width="30" height="6" className="flex-shrink-0">
                            <line x1="0" y1="3" x2="30" y2="3" stroke="#94a3b8" strokeWidth="2" />
                        </svg>
                        <span>Explicit Link</span>
                    </div>
                    <div className="flex items-center gap-2">
                        <svg width="30" height="6" className="flex-shrink-0">
                            <line x1="0" y1="3" x2="30" y2="3" stroke="#94a3b8" strokeWidth="2" strokeDasharray="5,3" />
                        </svg>
                        <span>Inferred Link</span>
                    </div>
                    <div className="flex items-center gap-2">
                        <svg width="30" height="6" className="flex-shrink-0">
                            <line x1="0" y1="3" x2="30" y2="3" stroke="#ef4444" strokeWidth="3" />
                        </svg>
                        <span className="text-red-300 font-bold">Contradiction</span>
                    </div>
                </div>
            </div>
        </div>
    );
};

// --- Timeline View ---
const TimelineView: React.FC<{ data: NarrativeMapResult }> = ({ data }) => {
    return (
        <div className="bg-slate-900 rounded-lg border border-slate-700 p-6 h-[600px] overflow-y-auto">
            <h3 className="text-lg font-bold text-slate-100 mb-6 sticky top-0 bg-slate-900 pb-4 border-b border-slate-700 z-10">Chronological Sequence</h3>
            <div className="space-y-8 relative pl-4 border-l-2 border-slate-700">
                {data.timeline.map((event, i) => (
