};

export default function NarrativeMapper({ onClose, onGenerate }: NarrativeMapperProps): React.ReactNode {
    const [file, setFile] = useState<File | null>(null);
    const [isLoading, setIsLoading] = useState(false);
    const [result, setResult] = useState<NarrativeMapResult | null>(null);
    const [viewMode, setViewMode] = useState<'graph' | 'timeline'>('graph');
    const [selectedNode, setSelectedNode] = useState<NarrativeNode | null>(null);
    const [error, setError] = useState<string | null>(null);

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) setFile(e.target.files[0]);
    };

    const handleGenerate = async () => {
        if (!file) return;
        setIsLoading(true);
        setError(null);
        try {
            const reader = new FileReader();
            reader.onload = async (e) => {
                const base64 = (e.target?.result as string).split(',')[1];
                const res = await onGenerate(base64, file.type, file.name);
                setResult(res);
            };
            reader.readAsDataURL(file);
        } catch (e) {
            setError("Failed to generate map.");
        } finally {
            setIsLoading(false);
        }
    };

    if (!result && !isLoading) {
        return (
            <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-sm flex justify-center items-center z-50 p-4">
                <div className="bg-slate-800 rounded-xl shadow-2xl w-full max-w-2xl p-8 border border-slate-700 relative">
                    <button onClick={onClose} className="absolute top-4 right-4 text-slate-400 hover:text-white">
                        <CloseIcon className="w-6 h-6" />
                    </button>
                    <div className="text-center mb-8">
                        <div className="bg-teal-900/30 p-4 rounded-full inline-block mb-4">
                            <BrainCircuitIcon className="w-12 h-12 text-teal-400" />
                        </div>
                        <h2 className="text-2xl font-bold text-slate-100">Narrative Mapper</h2>
                        <p className="text-slate-400 mt-2">Upload discovery to generate an interactive relationship graph and timeline.</p>
                    </div>

                    <div className="border-2 border-dashed border-slate-600 rounded-lg p-8 text-center bg-slate-900/50">
                        <input type="file" accept="application/pdf" onChange={handleFileChange} className="hidden" id="file-upload" />
                        <label htmlFor="file-upload" className="cursor-pointer block">
                            <DocumentIcon className="w-10 h-10 text-slate-500 mx-auto mb-2" />
                            <span className="text-blue-400 hover:text-blue-300 font-bold block mb-1">Click to Upload Discovery</span>
                            <span className="text-xs text-slate-500">{file ? file.name : "PDF Files only (Max 10MB)"}</span>
                        </label>
                    </div>

                    <button 
                        onClick={handleGenerate}
                        disabled={!file}
                        className="w-full mt-6 bg-teal-600 hover:bg-teal-700 text-white font-bold py-3 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                    >
                        Initialize Map
                    </button>
                    {error && <p className="text-red-400 text-center mt-4 text-sm">{error}</p>}
                </div>
            </div>
        );
    }

    if (isLoading) {
        return (
             <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-sm flex justify-center items-center z-50">
                 <div className="text-center">
                     <SpinnerIcon className="w-12 h-12 text-teal-400 mx-auto mb-4" />
                     <h3 className="text-xl font-bold text-slate-100 animate-pulse">Mapping Narrative...</h3>
                     <p className="text-slate-400">Extracting entities and inferring relationships.</p>
                 </div>
             </div>
        );
    }

    return (
        <div className="fixed inset-0 bg-slate-900 z-50 flex flex-col">
            {/* Header */}
            <div className="bg-slate-800 border-b border-slate-700 p-4 flex justify-between items-center shadow-md z-20">
                <div className="flex items-center gap-4">
                    <BrainCircuitIcon className="w-6 h-6 text-teal-400" />
                    <div>
                        <h2 className="text-xl font-bold text-slate-100">Narrative Map: {file?.name}</h2>
                        <p className="text-xs text-slate-400">Colorado Defense Context Active</p>
                    </div>
                </div>
                <div className="flex items-center gap-4">
                    <div className="bg-slate-900 rounded-lg p-1 flex border border-slate-700">
                        <button 
                            onClick={() => setViewMode('graph')}
                            className={`px-4 py-1.5 rounded-md text-sm font-bold transition-colors ${viewMode === 'graph' ? 'bg-teal-600 text-white' : 'text-slate-400 hover:text-slate-200'}`}
                        >
                            Graph View
                        </button>
                        <button 
                            onClick={() => setViewMode('timeline')}
                            className={`px-4 py-1.5 rounded-md text-sm font-bold transition-colors ${viewMode === 'timeline' ? 'bg-teal-600 text-white' : 'text-slate-400 hover:text-slate-200'}`}
                        >
                            Timeline View
                        </button>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-slate-700 rounded-full text-slate-400 hover:text-white">
                        <CloseIcon className="w-6 h-6" />
                    </button>
                </div>
            </div>

            {/* Main Content */}
            <div className="flex-grow flex overflow-hidden">
                {/* Visual Area */}
                <div className="flex-grow p-4 overflow-hidden relative">
                    {viewMode === 'graph' ? (
                        <GraphView data={result!} onNodeClick={setSelectedNode} />
                    ) : (
                        <TimelineView data={result!} />
                    )}
                </div>

                {/* Sidebar / Inspector */}
                <div className="w-96 bg-slate-800 border-l border-slate-700 flex flex-col shadow-xl z-10">
                    <div className="p-6 border-b border-slate-700">
                        <h3 className="text-lg font-bold text-slate-100 mb-2">Strategic Assessment</h3>
                        <p className="text-sm text-slate-300 leading-relaxed italic">
                            "{result?.strategicAssessment}"
                        </p>
                    </div>

                    <div className="flex-grow p-6 overflow-y-auto">
                        {selectedNode ? (
                            <div className="animate-[fadeIn_0.2s_ease-out]">
                                <div className="flex items-center gap-3 mb-4">
