const identifyJudges = async (summary: string): Promise<JudgeSummary[]> => {
  const truncatedSummary = summary.length > 50000 ? summary.substring(0, 50000) + "...(truncated)" : summary;
  const prompt = `From the following legal summary, identify and list any judges mentioned. Return only their full names.\n\nSummary:\n${truncatedSummary}`;
  try {
      const response: GenerateContentResponse = await ai.models.generateContent({
          model: 'gemini-2.5-flash',
          contents: prompt,
          config: {
              responseMimeType: "application/json",
              responseSchema: {
                  type: Type.OBJECT,
                  properties: {
                      judges: {
                          type: Type.ARRAY,
                          description: 'A list of judge names identified in the summary.',
                          items: {
                              type: Type.OBJECT,
                              properties: {
                                  name: { type: Type.STRING, description: 'The full name of the judge.' }
                              },
                              required: ['name']
                          }
                      }
                  }
              }
          }
      });
      const parsed = safeParseJSON<{ judges: JudgeSummary[] }>(response.text);
      const rawJudges: JudgeSummary[] = parsed?.judges || [];
      const uniqueJudges = Array.from(new Set(rawJudges.map(j => j.name)))
                                .map(name => ({ name }));
      return uniqueJudges;
  } catch(error) {
      console.error("Failed to identify judges:", error);
      return [];
  }
};

export const getJudgeDetails = async (judgeName: string): Promise<JudgeDetail> => {
  const prompt = `You are an elite legal strategist. Research judge "${judgeName}" from the Denver Court System. 
  Your goal is to provide an "unfair advantage" by detailing their specific judicial tendencies, patterns in rulings, notable past cases (with outcomes and dates), and any relevant statistics (e.g., conviction rates if applicable, average sentence length, caseload type).

  CRITICAL DATA REQUESTS:
  1. **Ruling Patterns by Case Type:** Specifically look for win/loss ratios or outcome percentages for specific case types (e.g., "Civil: 60% Plaintiff Verdicts", "Criminal: 85% Conviction Rate").
  2. **Sentencing Averages:** If available, provide average sentencing lengths for common offenses (e.g., "DUI: 30 days suspended", "Assault: 2 years probation").
  3. **Disposition Time:** Average time to disposition.
  4. **Strategic Insights:** Specific advice for lawyers appearing before this judge.

  Prioritize information from official court records, legal journals, and reputable legal news sources.
  If no specific data is found for a category, state "Not available" for that category.`;

  try {
      const response: GenerateContentResponse = await ai.models.generateContent({
          model: 'gemini-3-pro-preview', // Use a powerful model for deep research
          contents: prompt,
          config: {
              tools: [{googleSearch: {}}], // Use Google Search for up-to-date information
              thinkingConfig: {
                  thinkingBudget: 32768, // Max budget for deep reasoning
              },
              responseMimeType: "application/json",
              responseSchema: {
                  type: Type.OBJECT,
                  properties: {
                      name: { type: Type.STRING, description: 'The full name of the judge.' },
                      tendencies: { type: Type.STRING, description: 'Detailed description of the judge\'s known judicial tendencies, biases, or preferred legal interpretations.' },
                      notableCases: {
                          type: Type.ARRAY,
                          description: 'A list of 3-5 notable past cases, including their names, outcomes, and approximate dates.',
                          items: {
                              type: Type.OBJECT,
                              properties: {
                                  caseName: { type: Type.STRING },
                                  outcome: { type: Type.STRING },
                                  date: { type: Type.STRING }
                              },
                              required: ['caseName', 'outcome', 'date']
                          }
                      },
                      statistics: {
                          type: Type.ARRAY,
                          description: 'Key statistics like total cases, conviction rate, average sentence, or caseload type, if available.',
                          items: {
                            type: Type.OBJECT,
                            properties: {
                              totalCases: { type: Type.NUMBER, description: 'Total number of cases handled.' },
                              convictionRate: { type: Type.STRING, description: 'Conviction rate (e.g., "75%").' },
                              averageSentence: { type: Type.STRING, description: 'Average sentence length (e.g., "2.5 years").' },
                              caseLoad: { type: Type.STRING, description: 'Type of caseload (e.g., "heavy", "moderate", "civil", "criminal").' },
                            },
                          }
                      },
                      rulingPatternsByCaseType: {
                          type: Type.ARRAY,
                          description: 'Detailed patterns of rulings broken down by different case types (e.g., criminal, civil, family), including any associated win/loss ratios or outcome percentages.',
                          items: {
                              type: Type.OBJECT,
                              properties: {
                                  caseType: { type: Type.STRING, description: 'The type of case (e.g., "Criminal", "Civil", "Family").' },
                                  pattern: { type: Type.STRING, description: 'Description of the judge\'s ruling pattern in this case type (e.g., "Generally pro-prosecution", "Often favors plaintiffs").' },
                                  percentage: { type: Type.STRING, description: 'Optional: A percentage or ratio indicating a bias or outcome frequency (e.g., "70% pro-prosecution", "60% Plaintiff Verdicts").' }
                              },
                              required: ['caseType', 'pattern']
                          }
                      },
                      averageTimeToDisposition: { type: Type.STRING, description: 'The average time it takes for cases to reach final disposition under this judge (e.g., "180 days", "6 months", "1.5 years").' },
                      sentencingData: {
                        type: Type.ARRAY,
                        description: 'Average sentencing lengths for specific offenses.',
                        items: {
                          type: Type.OBJECT,
                          properties: {
                            offense: { type: Type.STRING, description: 'The specific offense (e.g., "DUI", "Assault", "Theft").' },
                            averageSentence: { type: Type.STRING, description: 'The average sentence or typical outcome (e.g., "30 days jail", "2 years probation").' }
                          },
                          required: ['offense', 'averageSentence']
                        }
                      },
                      strategicInsights: { type: Type.STRING, description: 'Specific strategic advice for lawyers appearing before this judge, offering an "unfair advantage".' },
                  },
                  required: ['name', 'tendencies', 'notableCases', 'strategicInsights']
              }
          },
          safetySettings: [
            { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_NONE },
            { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_NONE },
            { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_NONE },
            { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_NONE },
          ],
      });

      const parsed = safeParseJSON<JudgeDetail>(response.text);
      if (!parsed) throw new Error("API returned malformed JSON for judge details.");

      return {
        name: parsed.name || judgeName,
        tendencies: parsed.tendencies || "Not available.",
        notableCases: parsed.notableCases || [],
        statistics: parsed.statistics || [],
        rulingPatternsByCaseType: parsed.rulingPatternsByCaseType || [],
