import React, { useState, useCallback, useRef, useEffect, useMemo } from 'react';
import { NarrativeMapResult, NarrativeNode, NarrativeLink, TimelineEvent } from '../types';
import SpinnerIcon from './icons/SpinnerIcon';
import CloseIcon from './icons/CloseIcon';
import BrainCircuitIcon from './icons/BrainCircuitIcon';
import UserIcon from './icons/UserIcon';
import GavelIcon from './icons/GavelIcon'; // Institutions
import GlobeIcon from './icons/GlobeIcon'; // Locations
import DocumentIcon from './icons/DocumentIcon'; // Default/Event
import AlertIcon from './icons/AlertIcon';
import CalendarIcon from './icons/CalendarIcon';
import PdfIcon from './icons/PdfIcon';
import DownloadIcon from './icons/DownloadIcon';

interface NarrativeMapperProps {
    onClose: () => void;
    onGenerate: (base64Content: string, mimeType: string, fileName: string) => Promise<NarrativeMapResult>;
}

const MAX_FILE_SIZE_MB = 10;

// --- Node Icons Helper ---
const getNodeIcon = (type: string, className = "w-5 h-5") => {
    switch (type) {
        case 'person': return <UserIcon className={className} />;
        case 'location': return <GlobeIcon className={className} />;
        case 'institution': return <GavelIcon className={className} />;
        case 'event': return <CalendarIcon className={className} />;
        default: return <DocumentIcon className={className} />;
    }
};

const getNodeColor = (type: string, isBrady: boolean) => {
    if (isBrady) return 'bg-red-500 border-red-300 text-white';
    switch (type) {
        case 'person': return 'bg-blue-600 border-blue-400 text-white';
        case 'location': return 'bg-green-600 border-green-400 text-white';
        case 'institution': return 'bg-slate-600 border-slate-400 text-white';
        case 'event': return 'bg-purple-600 border-purple-400 text-white';
        default: return 'bg-slate-600 border-slate-400 text-white';
    }
};

// --- Evidence Badge Component ---
const EvidenceBadge: React.FC<{ tag: string }> = ({ tag }) => {
    // CRE 403 (Prejudice) -> Red/Orange
    // CRE 613 (Inconsistent) -> Purple
    // Hearsay -> Yellow
    let bgClass = "bg-slate-700 text-slate-300 border-slate-500";

    if (tag.includes("403")) bgClass = "bg-orange-900/80 text-orange-200 border-orange-500/50";
    else if (tag.includes("613") || tag.includes("Inconsistent")) bgClass = "bg-purple-900/80 text-purple-200 border-purple-500/50";
    else if (tag.includes("Brady")) bgClass = "bg-red-900/90 text-white border-red-500 animate-pulse";
    else if (tag.includes("Hearsay")) bgClass = "bg-yellow-900/60 text-yellow-200 border-yellow-500/50";

    return (
        <span className={`px-1.5 py-0.5 rounded text-[9px] font-bold uppercase border ${bgClass} whitespace-nowrap shadow-sm`}>
            {tag}
        </span>
    );
};

// --- Custom Graph View (SVG) ---
interface GraphViewProps {
    data: NarrativeMapResult;
    onNodeClick: (node: NarrativeNode) => void;
    activeNodeId: string | null;
}

const GraphView: React.FC<GraphViewProps> = ({ data, onNodeClick, activeNodeId }) => {
    const svgRef = useRef<SVGSVGElement>(null);
    const [positions, setPositions] = useState<Record<string, { x: number, y: number }>>({});
    const [draggingId, setDraggingId] = useState<string | null>(null);

    // Initial Layout Calculation
    useEffect(() => {
        const width = 800;
        const height = 600;
        const newPositions: Record<string, { x: number, y: number }> = {};

        const centerX = width / 2;
        const centerY = height / 2;

        const people = data.nodes.filter(n => n.type === 'person');
        const others = data.nodes.filter(n => n.type !== 'person');

        people.forEach((node, i) => {
            const angle = (i / people.length) * 2 * Math.PI;
            const radius = 150;
            newPositions[node.id] = {
                x: centerX + Math.cos(angle) * radius,
                y: centerY + Math.sin(angle) * radius
            };
        });

        others.forEach((node, i) => {
            const angle = (i / others.length) * 2 * Math.PI;
            const radius = 280;
            newPositions[node.id] = {
                x: centerX + Math.cos(angle) * radius,
                y: centerY + Math.sin(angle) * radius
            };
        });

        setPositions(newPositions);
    }, [data]);

    const handleMouseDown = (id: string) => setDraggingId(id);
    const handleMouseUp = () => setDraggingId(null);
    const handleMouseMove = (e: React.MouseEvent) => {
        if (!draggingId || !svgRef.current) return;
        const rect = svgRef.current.getBoundingClientRect();
        setPositions(prev => ({
            ...prev,
            [draggingId]: {
                x: e.clientX - rect.left,
                y: e.clientY - rect.top
            }
        }));
    };

    return (
        <div className="bg-slate-900/50 rounded-lg overflow-hidden relative h-full w-full">
            {/* Background Grid for "Matrix" feel */}
            <div className="absolute inset-0 opacity-10 pointer-events-none" 
                 style={{ backgroundImage: 'linear-gradient(#334155 1px, transparent 1px), linear-gradient(90deg, #334155 1px, transparent 1px)', backgroundSize: '40px 40px' }}>
            </div>

            <svg 
                ref={svgRef}
                width="100%" 
                height="100%" 
                viewBox="0 0 800 600"
                onMouseMove={handleMouseMove}
                onMouseUp={handleMouseUp}
                onMouseLeave={handleMouseUp}
                className="cursor-move"
            >
                <defs>
                    <marker id="arrow-explicit" markerWidth="10" markerHeight="7" refX="29" refY="3.5" orient="auto">
                        <polygon points="0 0, 10 3.5, 0 7" fill="#94a3b8" />
                    </marker>
                    <marker id="arrow-inferred" markerWidth="10" markerHeight="7" refX="29" refY="3.5" orient="auto">
                        <polygon points="0 0, 10 3.5, 0 7" fill="#64748b" />
                    </marker>
                     <marker id="arrow-contradiction" markerWidth="10" markerHeight="7" refX="29" refY="3.5" orient="auto">
                        <polygon points="0 0, 10 3.5, 0 7" fill="#ef4444" />
                    </marker>
                </defs>

                {/* Links */}
                {data.links.map((link, i) => {
                    const start = positions[link.source];
                    const end = positions[link.target];
                    if (!start || !end) return null;

                    const type = link.type?.toLowerCase() || 'explicit';
                    let strokeColor = '#94a3b8'; // slate-400
                    let strokeDash = '0';
                    let strokeWidth = '2';
                    let markerEnd = 'url(#arrow-explicit)';

                    if (type === 'inferred') {
                        strokeColor = '#64748b'; // slate-500
                        strokeDash = '5,5';
                        markerEnd = 'url(#arrow-inferred)';
                    } else if (type === 'contradiction') {
                        strokeColor = '#ef4444'; // red-500
                        strokeWidth = '3';
                        markerEnd = 'url(#arrow-contradiction)';
                    }

                    // Midpoint for label
                    const midX = (start.x + end.x) / 2;
                    const midY = (start.y + end.y) / 2;

                    return (
                        <g key={i}>
                            <line 
                                x1={start.x} y1={start.y} 
                                x2={end.x} y2={end.y} 
                                stroke={strokeColor} 
                                strokeWidth={strokeWidth} 
                                strokeDasharray={strokeDash}
                                markerEnd={markerEnd}
                                opacity="0.6"
                            />
                            {/* Link Label using ForeignObject for better HTML styling (backgrounds + icons) */}
                            <foreignObject 
                                x={midX - 75} 
                                y={midY - 12} 
                                width="150" 
                                height="24"
                            >
                                <div className="flex justify-center items-center w-full h-full pointer-events-none">
                                    <div className={`flex items-center gap-1.5 px-1.5 py-0.5 rounded shadow-md border backdrop-blur-sm ${
                                        type === 'contradiction' 
                                            ? 'bg-red-950/90 text-red-100 border-red-500/60' 
                                            : 'bg-slate-900/80 text-slate-300 border-slate-700/50'
                                    }`}>
                                        {type === 'contradiction' && (
                                            <AlertIcon className="w-3 h-3 text-red-500 flex-shrink-0" />
                                        )}
                                        <span className="text-[10px] font-mono font-bold whitespace-nowrap truncate max-w-[130px]">
                                            {link.label}
                                        </span>
                                    </div>
                                </div>
                            </foreignObject>
                        </g>
                    );
                })}

                {/* Nodes */}
                {data.nodes.map((node) => {
                    const pos = positions[node.id];
                    if (!pos) return null;
                    const isActive = activeNodeId === node.id;
                    const fill = !!node.bradyFlag ? '#ef4444' : (node.type === 'person' ? '#2563eb' : '#475569');

                    return (
                        <g 
                            key={node.id} 
                            transform={`translate(${pos.x}, ${pos.y})`}
                            onMouseDown={() => handleMouseDown(node.id)}
                            onClick={() => onNodeClick(node)}
                            className={`cursor-pointer transition-opacity ${isActive ? 'opacity-100' : 'hover:opacity-90'}`}
                        >
                            {/* Highlight ring for active node */}
                            {isActive && <circle r="30" fill="none" stroke="#60a5fa" strokeWidth="2" strokeDasharray="4,2" className="animate-spin-slow" />}

                            <circle r="25" fill={fill} stroke="#fff" strokeWidth="2.5" className="shadow-lg" />

                            {/* Brady/Alert Icon Overlay */}
                            {node.bradyFlag && (
                                <g transform="translate(14, -28)">
                                   <circle r="10" fill="#7f1d1d" stroke="#ef4444" />
                                   <text x="0" y="4" textAnchor="middle" fill="#fff" fontSize="12" fontWeight="bold">!</text>
                                </g>
                            )}

                            <foreignObject x="-12" y="-12" width="24" height="24">
                                <div className="text-white flex justify-center drop-shadow-md">
                                    {getNodeIcon(node.type, "w-6 h-6")}
                                </div>
                            </foreignObject>

                            <text y="42" fill="#fff" fontSize="12" textAnchor="middle" fontWeight="bold" style={{ textShadow: '0 1px 3px rgba(0,0,0,1)' }}>
                                {node.label}
                            </text>

                            {/* Evidence Tags rendering in SVG via ForeignObject */}
                            {node.evidenceTags && node.evidenceTags.length > 0 && (
                                <foreignObject x="-40" y="50" width="80" height="60">
                                    <div className="flex flex-col items-center gap-1">
                                        {node.evidenceTags.slice(0, 2).map((tag, idx) => (
                                           <EvidenceBadge key={idx} tag={tag} /> 
                                        ))}
                                        {node.evidenceTags.length > 2 && <span className="text-[8px] text-slate-400">+{node.evidenceTags.length - 2} more</span>}
                                    </div>
                                </foreignObject>
                            )}
                        </g>
                    );
                })}
            </svg>
        </div>
    );
};

// --- Dual-Track Timeline View ---
const DualTrackTimeline: React.FC<{ events: TimelineEvent[], onEventClick: (nodeId?: string) => void }> = ({ events, onEventClick }) => {
    // Sort chronologically
    const sortedEvents = [...events].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    return (
        <div className="h-full overflow-y-auto pr-2 relative custom-scrollbar">
            {/* Center Line */}
            <div className="absolute left-1/2 top-0 bottom-0 w-px bg-slate-700/50 -translate-x-1/2 z-0"></div>

            <div className="space-y-6 py-4 relative z-10">
                {sortedEvents.map((event, i) => {
                    const isDefense = event.narrativeTrack === 'defense';
                    const isProsecution = event.narrativeTrack === 'prosecution';
                    // If undisputed or unspecified, center it? Or default to prosecution? Let's center undisputed.
                    const isUndisputed = !isDefense && !isProsecution;

                    return (
                        <div key={i} className={`flex w-full items-center ${isUndisputed ? 'justify-center' : isDefense ? 'justify-end' : 'justify-start'}`}>

                            {/* Card */}
                            <div 
                                onClick={() => onEventClick((event as any).relatedNodeId)} // Cast for compat if types slightly mismatched
                                className={`
                                    w-[45%] p-3 rounded-lg border cursor-pointer hover:scale-[1.02] transition-transform
                                    ${isDefense 
                                        ? 'bg-blue-900/20 border-blue-500/30 text-right mr-4' 
                                        : isProsecution 
                                            ? 'bg-red-900/20 border-red-500/30 text-left ml-4'
                                            : 'bg-slate-800 border-slate-600 text-center w-[80%] z-20 shadow-xl'
                                    }
                                `}
                            >
                                <div className={`flex items-center gap-2 mb-1 ${isDefense ? 'justify-end' : isProsecution ? 'justify-start' : 'justify-center'}`}>
                                    {isDefense && <span className="text-[10px] font-bold uppercase text-blue-400 tracking-wider">Defense Theory</span>}
                                    <span className="text-xs font-mono font-bold text-slate-300 bg-slate-900/50 px-2 py-0.5 rounded">{event.date}</span>
                                    {isProsecution && <span className="text-[10px] font-bold uppercase text-red-400 tracking-wider">State Theory</span>}
                                </div>
                                <p className="text-sm font-medium text-slate-200">{event.event}</p>
                                {event.citation && (
                                    <p className="text-[10px] text-slate-500 mt-1 font-mono truncate">{event.citation}</p>
                                )}
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

export default function NarrativeMapper({ onClose, onGenerate }: NarrativeMapperProps): React.ReactNode {
    const [file, setFile] = useState<File | null>(null);
    const [isLoading, setIsLoading] = useState(false);
    const [result, setResult] = useState<NarrativeMapResult | null>(null);
    const [selectedNode, setSelectedNode] = useState<NarrativeNode | null>(null);
    const [error, setError] = useState<string | null>(null);

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) setFile(e.target.files[0]);
    };

    const handleGenerate = async () => {
        if (!file) return;
        setIsLoading(true);
        setError(null);
        try {
            // Promisify the file reading to ensure we wait for it
            const base64 = await new Promise<string>((resolve, reject) => {
                const reader = new FileReader();
                reader.onload = () => {
                    const res = reader.result as string;
                    // split to get just base64
                    resolve(res.split(',')[1]);
                };
                reader.onerror = () => reject(new Error("Failed to read file"));
                reader.readAsDataURL(file);
            });

            const res = await onGenerate(base64, file.type, file.name);
            setResult(res);
        } catch (e) {
            console.error(e);
            setError("Failed to generate map. " + (e instanceof Error ? e.message : String(e)));
        } finally {
            setIsLoading(false);
        }
    };

    const handleExport = () => {
        alert("Generating Courtroom Exhibit PDF with Colorado Citation formatting...");
        // In a real app, this would use jspdf to capture the SVG and Timeline state
    };

    const handleTimelineEventClick = (nodeId?: string) => {
        if (nodeId && result) {
            const node = result.nodes.find(n => n.id === nodeId);
            if (node) setSelectedNode(node);
        }
    };

    if (!result && !isLoading) {
        return (
            <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-sm flex justify-center items-center z-50 p-4">
                <div className="bg-slate-800 rounded-xl shadow-2xl w-full max-w-2xl p-8 border border-slate-700 relative">
                    <button onClick={onClose} className="absolute top-4 right-4 text-slate-400 hover:text-white">
                        <CloseIcon className="w-6 h-6" />
                    </button>
                    <div className="text-center mb-8">
                        <div className="bg-teal-900/30 p-4 rounded-full inline-block mb-4">
                            <BrainCircuitIcon className="w-12 h-12 text-teal-400" />
                        </div>
                        <h2 className="text-2xl font-bold text-slate-100">Colorado Defense Mapper</h2>
                        <p className="text-slate-400 mt-2">Upload discovery to generate a dual-track narrative timeline and relationship matrix.</p>
                    </div>

                    <div className="border-2 border-dashed border-slate-600 rounded-lg p-8 text-center bg-slate-900/50">
                        <input type="file" accept="application/pdf" onChange={handleFileChange} className="hidden" id="file-upload" />
                        <label htmlFor="file-upload" className="cursor-pointer block">
                            <DocumentIcon className="w-10 h-10 text-slate-500 mx-auto mb-2" />
                            <span className="text-blue-400 hover:text-blue-300 font-bold block mb-1">Click to Upload Discovery</span>
                            <span className="text-xs text-slate-500">{file ? file.name : "PDF Files only (Max 10MB)"}</span>
                        </label>
                    </div>

                    <button 
                        onClick={handleGenerate}
                        disabled={!file}
                        className="w-full mt-6 bg-teal-600 hover:bg-teal-700 text-white font-bold py-3 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                    >
                        Initialize Map
                    </button>
                    {error && <p className="text-red-400 text-center mt-4 text-sm">{error}</p>}
                </div>
            </div>
        );
    }

    if (isLoading) {
        return (
             <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-sm flex justify-center items-center z-50">
                 <div className="text-center">
                     <SpinnerIcon className="w-12 h-12 text-teal-400 mx-auto mb-4" />
                     <h3 className="text-xl font-bold text-slate-100 animate-pulse">Analyzing Narrative...</h3>
                     <p className="text-slate-400">Extracting entities, checking Brady lists, and inferring timeline tracks.</p>
                 </div>
             </div>
        );
    }

    return (
        <div className="fixed inset-0 bg-slate-950 z-50 flex flex-col">
            {/* Header */}
            <div className="bg-slate-900 border-b border-slate-800 p-4 flex justify-between items-center shadow-md z-20">
                <div className="flex items-center gap-4">
                    <BrainCircuitIcon className="w-6 h-6 text-teal-400" />
                    <div>
                        <h2 className="text-xl font-bold text-slate-100">Narrative Map: {file?.name}</h2>
                        <div className="flex items-center gap-2">
                            <span className="text-[10px] bg-red-900/30 text-red-400 border border-red-900/50 px-1.5 rounded">Prosecution Theory</span>
                            <span className="text-[10px] bg-blue-900/30 text-blue-400 border border-blue-900/50 px-1.5 rounded">Defense Theory</span>
                        </div>
                    </div>
                </div>
                <div className="flex items-center gap-4">
                     <button 
                        onClick={handleExport}
                        className="flex items-center px-3 py-1.5 bg-slate-800 hover:bg-slate-700 border border-slate-600 rounded text-sm font-bold text-slate-200 transition-colors"
                    >
                        <DownloadIcon className="w-4 h-4 mr-2" />
                        Courtroom Exhibit
                    </button>
                    <button onClick={onClose} className="p-2 hover:bg-slate-800 rounded-full text-slate-400 hover:text-white">
                        <CloseIcon className="w-6 h-6" />
                    </button>
                </div>
            </div>

            {/* Main Content - Split View */}
            <div className="flex-grow flex overflow-hidden">

                {/* Left Panel: Dual-Track Timeline (40%) */}
                <div className="w-[40%] bg-slate-900 border-r border-slate-800 flex flex-col">
                    <div className="p-4 border-b border-slate-800 bg-slate-900 z-10">
                        <h3 className="text-sm font-bold text-slate-400 uppercase tracking-wider flex items-center">
                            <CalendarIcon className="w-4 h-4 mr-2" />
                            Chronological Narrative
                        </h3>
                    </div>
                    <div className="flex-grow p-4 overflow-hidden">
                        <DualTrackTimeline events={result!.timeline} onEventClick={handleTimelineEventClick} />
                    </div>
                </div>

                {/* Right Panel: Relationship Matrix (60%) */}
                <div className="w-[60%] flex flex-col relative bg-slate-950">
                    <div className="absolute top-4 left-4 z-10 pointer-events-none">
                        <h3 className="text-sm font-bold text-slate-400 uppercase tracking-wider flex items-center bg-slate-900/80 px-2 py-1 rounded backdrop-blur-sm">
                            <BrainCircuitIcon className="w-4 h-4 mr-2" />
                            Relationship Matrix
                        </h3>
                    </div>

                    <div className="flex-grow relative">
                        <GraphView 
                            data={result!} 
                            onNodeClick={setSelectedNode} 
                            activeNodeId={selectedNode?.id || null}
                        />
                    </div>

                    {/* Inspector / Assessment Panel (Bottom Overlay) */}
                    <div className="h-[30%] bg-slate-900 border-t border-slate-800 flex shadow-2xl z-20">
                         {/* Assessment */}
                        <div className="w-1/2 p-6 border-r border-slate-800 overflow-y-auto">
                            <h3 className="text-xs font-bold text-teal-400 uppercase mb-2">Strategic Assessment</h3>
                            <p className="text-sm text-slate-300 leading-relaxed italic">
                                "{result?.strategicAssessment}"
                            </p>
                        </div>

                        {/* Node Details */}
                        <div className="w-1/2 p-6 overflow-y-auto">
                            {selectedNode ? (
                                <div className="animate-[fadeIn_0.2s_ease-out]">
                                    <div className="flex items-center justify-between mb-2">
                                        <div className="flex items-center gap-3">
                                            <div className={`p-2 rounded-lg ${getNodeColor(selectedNode.type, false).replace('text-white', '')} bg-opacity-20`}>
                                                {getNodeIcon(selectedNode.type, "w-6 h-6 text-white")}
                                            </div>
                                            <div>
                                                <h4 className="text-lg font-bold text-slate-100">{selectedNode.label}</h4>
                                                <span className="text-[10px] uppercase font-bold text-slate-500 tracking-wider">{selectedNode.type}</span>
                                            </div>
                                        </div>
                                        {/* Tags */}
                                        <div className="flex flex-wrap gap-1 justify-end max-w-[50%]">
                                            {selectedNode.bradyFlag && <EvidenceBadge tag="Brady Alert" />}
                                            {selectedNode.evidenceTags?.map((tag, i) => <EvidenceBadge key={i} tag={tag} />)}
                                        </div>
                                    </div>

                                    {selectedNode.bradyFlag && (
                                        <div className="bg-red-900/20 border border-red-500/30 rounded p-2 mb-3 flex items-start gap-2">
                                            <AlertIcon className="w-4 h-4 text-red-400 flex-shrink-0 mt-0.5" />
                                            <div>
                                                <p className="text-xs font-bold text-red-300">C.R.S. § 16-15-103 Alert</p>
                                                <p className="text-[11px] text-red-200/80">{selectedNode.bradyFlag}</p>
                                            </div>
                                        </div>
                                    )}

                                    <div className="text-sm text-slate-300 mb-2">
                                        {selectedNode.description || "No description."}
                                    </div>

                                    {selectedNode.sourceCitation && (
                                        <div className="bg-slate-800 p-2 rounded border border-slate-700">
                                            <span className="text-[10px] text-slate-500 font-bold uppercase block mb-0.5">Source</span>
                                            <p className="text-xs text-blue-300 font-mono">{selectedNode.sourceCitation}</p>
                                        </div>
                                    )}
                                </div>
                            ) : (
                                <div className="h-full flex flex-col items-center justify-center text-slate-600">
                                    <BrainCircuitIcon className="w-8 h-8 mb-2 opacity-20" />
                                    <p className="text-xs">Select a node to view evidence & citations</p>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { DocumentAnalysisResult } from '../types';
import { askDocumentQuestion } from '../services/geminiService';
import SpinnerIcon from './icons/SpinnerIcon';
import DocumentIcon from './icons/DocumentIcon';
import CloseIcon from './icons/CloseIcon';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import GavelIcon from './icons/GavelIcon'; // For entities
import CalendarIcon from './icons/CalendarIcon'; // For dates
import UserIcon from './icons/UserIcon'; // For parties
import NumberIcon from './icons/NumberIcon'; // For case numbers
import BrainCircuitIcon from './icons/BrainCircuitIcon'; // For processing state
import BookmarkIcon from './icons/BookmarkIcon';
import BookmarkFilledIcon from './icons/BookmarkFilledIcon';
import QuestionMarkIcon from './icons/QuestionMarkIcon'; // For Q&A section

interface DocumentAnalysisModalProps {
    onClose: () => void;
    onAnalyze: (base64Content: string, mimeType: string, fileName: string) => Promise<void>;
    result: DocumentAnalysisResult | null;
    isLoading: boolean;
    error: string | null;
    onSave: (result: DocumentAnalysisResult) => void;
    onRemoveSave: (result: DocumentAnalysisResult) => void;
    isSaved: boolean;
}

const MAX_FILE_SIZE_MB = 10; // Client-side limit

const ProcessingView: React.FC = () => {
    const [progress, setProgress] = React.useState(0);
    const [messageIndex, setMessageIndex] = React.useState(0);

    const messages = [
        "Reading document structure...",
        "Identifying judges and parties...",
        "Extracting key legal arguments...",
        "Cross-referencing strategic patterns...",
        "Generating unfair advantage insights...",
        "Finalizing strategic report..."
    ];

    React.useEffect(() => {
        // Simulated progress that slows down as it approaches 90%
        const timer = setInterval(() => {
            setProgress((oldProgress) => {
                if (oldProgress >= 90) return 90;
                const remaining = 90 - oldProgress;
                // Move faster at start, slower at end
                const step = Math.max(0.5, remaining * 0.1); 
                return Math.min(oldProgress + step, 90);
            });
        }, 200);

        const msgTimer = setInterval(() => {
             setMessageIndex(prev => (prev + 1) % messages.length);
        }, 2500);

        return () => {
            clearInterval(timer);
            clearInterval(msgTimer);
        };
    }, []);

    return (
        <div className="flex flex-col items-center justify-center py-20 px-6 animate-[fadeIn_0.5s_ease-in-out]">
            <style>{`@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }`}</style>

            <div className="relative w-24 h-24 mb-8">
                {/* Outer static ring */}
                <div className="absolute inset-0 rounded-full border-4 border-slate-700/50"></div>
                {/* Spinning gradient ring */}
                <div className="absolute inset-0 rounded-full border-4 border-transparent border-t-blue-500 border-r-blue-500/50 animate-spin"></div>
                {/* Pulse effect */}
                <div className="absolute inset-0 rounded-full bg-blue-500/10 animate-ping"></div>
                {/* Icon */}
                <div className="absolute inset-0 flex items-center justify-center">
                    <BrainCircuitIcon className="w-10 h-10 text-blue-400" />
                </div>
            </div>

            <h3 className="text-2xl font-bold text-slate-100 mb-2">Analyzing Document</h3>

            <div className="h-6 mb-8">
                <p className="text-blue-300 font-medium animate-pulse text-center">
                    {messages[messageIndex]}
                </p>
            </div>

            {/* Progress Bar */}
            <div className="w-full max-w-sm h-1.5 bg-slate-700 rounded-full overflow-hidden mb-3">
                <div 
                    className="h-full bg-gradient-to-r from-blue-500 via-indigo-500 to-purple-500 transition-all duration-300 ease-out"
                    style={{ width: `${progress}%` }}
                ></div>
            </div>

            <p className="text-xs text-slate-500">
                This utilizes deep reasoning and may take up to 30 seconds.
            </p>
        </div>
    );
};

const getEntityIcon = (type: string) => {
  switch (type) {
    case 'judge': return <GavelIcon className="w-4 h-4 mr-2 text-yellow-400" />;
    case 'party': return <UserIcon className="w-4 h-4 mr-2 text-green-400" />;
    case 'date': return <CalendarIcon className="w-4 h-4 mr-2 text-blue-400" />;
    case 'case_number': return <NumberIcon className="w-4 h-4 mr-2 text-purple-400" />;
    default: return <DocumentIcon className="w-4 h-4 mr-2 text-slate-400" />;
  }
}

interface ChatMessage {
    role: 'user' | 'ai';
    content: string;
}

export default function DocumentAnalysisModal({ onClose, onAnalyze, result, isLoading, error, onSave, onRemoveSave, isSaved }: DocumentAnalysisModalProps): React.ReactNode {
    const [selectedFile, setSelectedFile] = useState<File | null>(null);
    const [dragActive, setDragActive] = useState(false);
    const inputRef = useRef<HTMLInputElement>(null);
    const [localError, setLocalError] = useState<string | null>(null);

    // Chat State
    const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
    const [questionInput, setQuestionInput] = useState('');
    const [isAsking, setIsAsking] = useState(false);
    const chatEndRef = useRef<HTMLDivElement>(null);

    // Scroll to bottom of chat when history changes
    useEffect(() => {
        if (chatEndRef.current) {
            chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
        }
    }, [chatHistory, isAsking]);

    const handleFileChange = useCallback((files: FileList | null) => {
        setLocalError(null);
        if (files && files.length > 0) {
            const file = files[0];
            if (file.type !== 'application/pdf') {
                setLocalError('Only PDF files are supported.');
                setSelectedFile(null);
                return;
            }
            if (file.size > MAX_FILE_SIZE_MB * 1024 * 1024) {
                setLocalError(`File size exceeds ${MAX_FILE_SIZE_MB}MB limit.`);
                setSelectedFile(null);
                return;
            }
            setSelectedFile(file);
        } else {
            setSelectedFile(null);
        }
    }, []);

    const handleDrag = useCallback((e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        if (e.type === 'dragenter' || e.type === 'dragover') {
            setDragActive(true);
        } else if (e.type === 'dragleave') {
            setDragActive(false);
        }
    }, []);

    const handleDrop = useCallback((e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setDragActive(false);
        if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
            handleFileChange(e.dataTransfer.files);
            e.dataTransfer.clearData();
        }
    }, [handleFileChange]);

    const handleUploadButtonClick = useCallback(() => {
        inputRef.current?.click();
    }, []);

    const handleAnalyzeClick = useCallback(async () => {
        if (!selectedFile) return;

        setLocalError(null);
        setChatHistory([]); // Clear previous chat

        try {
            // Promisify file reading
            const base64Content = await new Promise<string>((resolve, reject) => {
                const reader = new FileReader();
                reader.onload = (e) => {
                    const base64 = e.target?.result as string;
                    resolve(base64.split(',')[1]);
                };
                reader.onerror = () => reject(new Error("Failed to read file"));
                reader.readAsDataURL(selectedFile);
            });

            await onAnalyze(base64Content, selectedFile.type, selectedFile.name);
        } catch (e) {
             setLocalError("Failed to read file or analyze.");
             console.error(e);
        }
    }, [selectedFile, onAnalyze]);

    const handleOverlayClick = useCallback((e: React.MouseEvent<HTMLDivElement>) => {
        if (e.target === e.currentTarget) {
            onClose();
        }
    }, [onClose]);

    const handleSaveToggle = () => {
        if (!result) return;
        if (isSaved) {
            onRemoveSave(result);
        } else {
            onSave(result);
        }
    };

    const handleAskQuestion = async () => {
        if (!questionInput.trim() || !result) return;

        const userQ = questionInput.trim();
        setQuestionInput(''); // Clear input immediately
        setChatHistory(prev => [...prev, { role: 'user', content: userQ }]);
        setIsAsking(true);

        try {
            const answer = await askDocumentQuestion(result, userQ);
            setChatHistory(prev => [...prev, { role: 'ai', content: answer }]);
        } catch (err) {
            setChatHistory(prev => [...prev, { role: 'ai', content: "I encountered an error trying to answer that. Please try again." }]);
        } finally {
            setIsAsking(false);
        }
    };

    const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            handleAskQuestion();
        }
    };

    return (
        <div
            className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm flex justify-center items-center z-50 p-4"
            onClick={handleOverlayClick}
            aria-modal="true"
            role="dialog"
        >
            <div className="bg-slate-800 rounded-lg shadow-xl max-w-3xl w-full max-h-[90vh] overflow-y-auto relative border border-slate-700">
                <div className="flex justify-between items-center p-4 border-b border-slate-700">
                    <h2 className="text-2xl font-bold text-slate-100 flex items-center">
                        <DocumentIcon className="w-6 h-6 mr-3 text-blue-400" />
                        Document Intelligence
                    </h2>
                    <div className="flex items-center gap-2">
                        {result && (
                            <button
                                onClick={handleSaveToggle}
                                className="p-2 rounded-full text-slate-400 hover:bg-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-colors"
                                title={isSaved ? "Unsave Analysis" : "Save Analysis"}
                            >
                                {isSaved ? (
                                    <BookmarkFilledIcon className="w-6 h-6 text-yellow-400" />
                                ) : (
                                    <BookmarkIcon className="w-6 h-6" />
                                )}
                            </button>
                        )}
                        <button
                            onClick={onClose}
                            className="p-2 rounded-full text-slate-400 hover:bg-slate-700 hover:text-slate-100 focus:outline-none focus:ring-2 focus:ring-blue-500"
                            title="Close"
                        >
                            <CloseIcon className="w-6 h-6" />
                        </button>
                    </div>
                </div>

                <div className="p-6">
                    {localError && (
                        <div className="bg-red-500/10 border border-red-500/30 text-red-300 px-4 py-3 rounded-lg mb-4" role="alert">
                            <strong className="font-extrabold">Error: </strong>
                            <span className="block sm:inline">{localError}</span>
                        </div>
                    )}
                    {error && ( // Global analysis error from App.tsx
                        <div className="bg-red-500/10 border border-red-500/30 text-red-300 px-4 py-3 rounded-lg mb-4" role="alert">
                            <strong className="font-extrabold">Analysis Error: </strong>
                            <span className="block sm:inline">{error}</span>
                        </div>
                    )}

                    {!result && !isLoading ? (
                        <>
                            <div
                                onDragEnter={handleDrag}
                                onDragLeave={handleDrag}
                                onDragOver={handleDrag}
                                onDrop={handleDrop}
                                onClick={handleUploadButtonClick}
                                className={`flex flex-col items-center justify-center p-8 border-2 border-dashed rounded-lg cursor-pointer transition-colors ${
                                    dragActive ? 'border-blue-500 bg-blue-500/10' : 'border-slate-600 hover:border-blue-500'
                                }`}
                            >
                                <input
                                    ref={inputRef}
                                    type="file"
                                    accept="application/pdf"
                                    onChange={(e) => handleFileChange(e.target.files)}
                                    className="hidden"
                                />
                                <DocumentIcon className="w-12 h-12 text-slate-400 mb-4" />
                                <p className="text-lg text-slate-300 text-center">
                                    Drag & drop your PDF here, or <span className="text-blue-400 font-semibold">click to upload</span>
                                </p>
                                <p className="text-sm text-slate-400 mt-2">Max file size: {MAX_FILE_SIZE_MB}MB (PDF only)</p>
                                {selectedFile && (
                                    <div className="mt-4 flex items-center justify-center gap-3">
                                        <p className="text-slate-200">Selected: <span className="font-semibold text-blue-300">{selectedFile.name}</span></p>
                                        <button 
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                setSelectedFile(null);
                                            }}
                                            className="text-slate-400 hover:text-red-400 transition-colors"
                                            title="Remove file"
                                        >
                                            <CloseIcon className="w-5 h-5" />
                                        </button>
                                    </div>
                                )}
                            </div>
                            <button
                                onClick={handleAnalyzeClick}
                                disabled={!selectedFile || isLoading}
                                className="mt-6 w-full inline-flex justify-center items-center px-4 py-3 border border-transparent text-base font-bold rounded-md shadow-sm text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:bg-slate-700 disabled:cursor-not-allowed transition-colors"
                            >
                                {isLoading ? <SpinnerIcon className="mr-3" /> : <DocumentIcon className="w-5 h-5 mr-2" />}
                                Analyze Document
                            </button>
                        </>
                    ) : isLoading ? (
                        <ProcessingView />
                    ) : result ? (
                        <div className="space-y-8 text-slate-200 animate-[fadeIn_0.5s_ease-in-out]">
                             <style>{`@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }`}</style>
                            <h3 className="text-xl font-bold text-blue-300 flex items-center mb-4">
                                <DocumentIcon className="w-6 h-6 mr-3 text-blue-400" />
                                Analysis for: {result.fileName}
                            </h3>

                            <div>
                                <h4 className="text-lg font-bold text-yellow-300 mb-2">Strategic Summary</h4>
                                <ReactMarkdown remarkPlugins={[remarkGfm]} className="leading-relaxed whitespace-pre-wrap text-slate-200">
                                    {result.strategicSummary}
                                </ReactMarkdown>
                            </div>

                            <div>
                                <h4 className="text-lg font-bold text-green-300 mb-2">Key Arguments/Positions</h4>
                                {result.keyArguments.length > 0 ? (
                                    <ul className="list-disc list-inside space-y-1 text-slate-200">
                                        {result.keyArguments.map((arg, index) => <li key={index}>{arg}</li>)}
                                    </ul>
                                ) : <p className="text-slate-400">Not available.</p>}
                            </div>

                            <div>
                                <h4 className="text-lg font-bold text-purple-300 mb-2">Identified Entities</h4>
                                {result.identifiedEntities.length > 0 ? (
                                    <ul className="space-y-1">
                                        {result.identifiedEntities.map((entity, index) => (
                                            <li key={index} className="flex items-center text-slate-200">
                                                {getEntityIcon(entity.type)}
                                                <span className="font-semibold capitalize mr-1">{entity.type}:</span> {entity.value}
                                            </li>
                                        ))}
                                    </ul>
                                ) : <p className="text-slate-400">Not available.</p>}
                            </div>

                            <div>
                                <h4 className="text-lg font-bold text-orange-300 mb-2">Actionable Insights</h4>
                                {result.actionableInsights.length > 0 ? (
                                    <ul className="list-decimal list-inside space-y-1 text-slate-200">
                                        {result.actionableInsights.map((insight, index) => <li key={index}>{insight}</li>)}
                                    </ul>
                                ) : <p className="text-slate-400">Not available.</p>}
                            </div>

                            {/* Q&A / Chat Section */}
                            <div className="mt-8 pt-8 border-t border-slate-700">
                                <h4 className="text-lg font-bold text-slate-100 mb-4 flex items-center">
                                    <QuestionMarkIcon className="w-5 h-5 mr-2 text-blue-400" />
                                    Legal Counsel & Q&A
                                </h4>
                                <p className="text-sm text-slate-400 mb-4">
                                    Ask specific questions about laws, rules cited, or explain why you think the analysis is wrong to get a re-evaluation.
                                </p>

                                <div className="space-y-4 mb-4">
                                    {chatHistory.map((msg, index) => (
                                        <div key={index} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                                            <div className={`max-w-[85%] rounded-lg p-3 ${
                                                msg.role === 'user' 
                                                    ? 'bg-blue-600 text-white rounded-br-none' 
                                                    : 'bg-slate-700 text-slate-200 rounded-bl-none'
                                            }`}>
                                                <div className="text-xs font-bold mb-1 opacity-75">
                                                    {msg.role === 'user' ? 'You' : 'AI Counsel'}
                                                </div>
                                                <ReactMarkdown 
                                                    remarkPlugins={[remarkGfm]} 
                                                    className="prose prose-invert prose-sm"
                                                    components={{
                                                        p: ({node, ...props}) => <p className="mb-2 last:mb-0" {...props} />
                                                    }}
                                                >
                                                    {msg.content}
                                                </ReactMarkdown>
                                            </div>
                                        </div>
                                    ))}
                                    {isAsking && (
                                        <div className="flex justify-start">
                                            <div className="bg-slate-700 text-slate-200 rounded-lg rounded-bl-none p-4 flex items-center space-x-2">
                                                 <SpinnerIcon className="w-4 h-4 text-blue-400" />
                                                 <span className="text-sm">Researching your question...</span>
                                            </div>
                                        </div>
                                    )}
                                    <div ref={chatEndRef} />
                                </div>

                                <div className="relative">
                                    <textarea
                                        value={questionInput}
                                        onChange={(e) => setQuestionInput(e.target.value)}
                                        onKeyDown={handleKeyDown}
                                        placeholder="Ask a legal question or provide a correction..."
                                        className="w-full bg-slate-900 border border-slate-600 rounded-lg p-3 pr-12 text-slate-100 placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500 resize-none"
                                        rows={2}
                                        disabled={isAsking}
                                    />
                                    <button
                                        onClick={handleAskQuestion}
                                        disabled={!questionInput.trim() || isAsking}
                                        className="absolute right-2 bottom-2 p-2 bg-blue-600 hover:bg-blue-700 text-white rounded-md disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                                        title="Send"
                                    >
                                        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-5 h-5">
                                            <path d="M3.105 2.289a.75.75 0 00-.826.95l1.414 4.925A1.5 1.5 0 005.135 9.25h6.115a.75.75 0 010 1.5H5.135a1.5 1.5 0 00-1.442 1.086l-1.414 4.926a.75.75 0 00.826.95 28.896 28.896 0 0015.293-7.154.75.75 0 000-1.115A28.897 28.897 0 003.105 2.289z" />
                                        </svg>
                                    </button>
                                </div>
                            </div>
                        </div>
                    ) : null}
                </div>
            </div>
        </div>
    );
}

