  const [showSuggestions, setShowSuggestions] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(-1);
  const [showHistory, setShowHistory] = useState(false);
  const [historyItems, setHistoryItems] = useState<SearchParams[]>([]);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const suggestionRef = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    const textarea = textareaRef.current;
    if (textarea) {
      textarea.style.height = 'auto';
      textarea.style.height = `${Math.max(120, textarea.scrollHeight)}px`;
    }
  }, [params.query]);

  useEffect(() => {
    if (showHistory) setHistoryItems(getHistory());
  }, [showHistory]);

  const handleInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.target.value;
    setParams(prev => ({ ...prev, query: value }));
    if (value.length > 2) {
      const filtered = SUGGESTION_BANK.filter(s => s.toLowerCase().includes(value.toLowerCase())).slice(0, 5);
      setSuggestions(filtered);
      setShowSuggestions(filtered.length > 0);
    } else setShowSuggestions(false);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (showSuggestions) {
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setSelectedIndex(prev => (prev < suggestions.length - 1 ? prev + 1 : prev));
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        setSelectedIndex(prev => (prev > 0 ? prev - 1 : -1));
      } else if (e.key === 'Enter' && selectedIndex >= 0) {
        e.preventDefault();
        selectSuggestion(suggestions[selectedIndex]);
      } else if (e.key === 'Escape') setShowSuggestions(false);
      else if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); onSearch(); }
    } else if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); onSearch(); }
  };

  const selectSuggestion = (text: string) => {
    setParams(prev => ({ ...prev, query: text }));
    setShowSuggestions(false);
