            placeholder="EXECUTE_SELECTOR_INTEL..."
            className="w-full bg-black/60 border border-[#00ff41]/40 p-6 font-mono text-[#00ff41] text-2xl focus:outline-none focus:border-[#00ff41] focus:bg-[#00ff41]/5 transition-all min-h-[120px] placeholder:text-[#00ff41]/10 resize-none shadow-[inset_0_0_20px_rgba(0,255,65,0.05)]"
            disabled={isLoading}
          />
          <div className="absolute top-0 right-0 p-2"><div className="w-4 h-4 border-t border-r border-[#ff0033]"></div></div>
          <div className="absolute bottom-0 left-0 p-2"><div className="w-4 h-4 border-b border-l border-[#aa00ff]"></div></div>

          {showSuggestions && (
