    } else setShowSuggestions(false);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (showSuggestions) {
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setSelectedIndex(prev => (prev < suggestions.length - 1 ? prev + 1 : prev));
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        setSelectedIndex(prev => (prev > 0 ? prev - 1 : -1));
      } else if (e.key === 'Enter' && selectedIndex >= 0) {
        e.preventDefault();
        selectSuggestion(suggestions[selectedIndex]);
      } else if (e.key === 'Escape') setShowSuggestions(false);
      else if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); onSearch(); }
    } else if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); onSearch(); }
  };

  const selectSuggestion = (text: string) => {
    setParams(prev => ({ ...prev, query: text }));
    setShowSuggestions(false);
    setSelectedIndex(-1);
    textareaRef.current?.focus();
  };

  return (
    <div className="p-10 border-b border-white/5 relative">
      <div className="calibration-marks mark-tl mark-tr"></div>

      <div className="flex flex-col gap-8 relative z-10">
        <div className="flex justify-between items-center etched-label">
          <div className="flex items-center gap-3">
            <div className="glow-dot"></div>
            INTEL_ACQUISITION_CHANNEL
          </div>
          <button onClick={() => setShowHistory(!showHistory)} className="hover:text-white transition-colors flex items-center gap-2">
            <HistoryIcon className="w-3 h-3" />
            [ARCHIVE_LOGS]
          </button>
        </div>

        <div className="relative">
          <textarea
            ref={textareaRef}
            value={params.query}
            onChange={handleInputChange}
            onKeyDown={handleKeyDown}
            placeholder="EXECUTE_SELECTOR_DIAGNOSTIC..."
            className="w-full bg-white/[0.02] border border-white/10 p-8 font-mono text-white text-3xl focus:outline-none focus:border-white/30 focus:bg-white/[0.04] transition-all min-h-[140px] placeholder:text-white/5 resize-none shadow-inner"
            disabled={isLoading}
          />

          {showSuggestions && (
            <div className="absolute left-0 top-full mt-2 w-full bg-[#111] border border-white/10 z-50 shadow-2xl">
              <div className="p-3 etched-label bg-white/5 border-b border-white/5">[PROBABLE_MATCHES]</div>
              <div className="flex flex-col">
                {suggestions.map((s, i) => (
                  <button key={i} onClick={() => selectSuggestion(s)} className={`text-left p-4 border-b border-white/5 last:border-0 transition-all text-xs font-mono ${selectedIndex === i ? 'bg-white/10 text-white italic' : 'text-[#666]'}`}>
                    >> {s}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="flex flex-col gap-2">
            <label className="etched-label">Party Name Filter</label>
            <input 
              type="text" 
              placeholder="e.g. Acme Corp" 
              value={params.partyName || ''} 
              onChange={(e) => setParams({...params, partyName: e.target.value})} 
              className="w-full bg-white/[0.02] border border-white/10 text-white text-sm p-4 outline-none focus:border-white/30 placeholder:text-white/10 shadow-inner stencil-value" 
            />
          </div>
          <div className="flex flex-col gap-2">
            <label className="etched-label">Temporal Scope</label>
            <select 
              value={params.dateRange} 
