        <div className="flex flex-wrap items-center gap-6 mt-4">
          <button 
            onClick={onSearch}
            disabled={isLoading || !params.query.trim()}
            className="flex-grow px-12 py-6 bg-white text-black font-black uppercase italic tracking-tighter text-2xl hover:bg-[#ccc] disabled:opacity-20 transition-all flex items-center justify-center gap-4"
          >
            {isLoading ? <><SpinnerIcon className="w-6 h-6 animate-spin" /><span className="animate-pulse">PROCESSING...</span></> : '[EXECUTE_INTEL_SCAN]'}
          </button>

          <div className="flex gap-4">
            <button onClick={() => setIsAdvancedOpen(!isAdvancedOpen)} className={`px-6 py-6 border border-white/10 text-[10px] font-bold uppercase tracking-widest hover:bg-white/5 ${isAdvancedOpen ? 'bg-white/10' : ''}`}>
