import UserIcon from './icons/UserIcon';
import SparklesIcon from './icons/SparklesIcon';

interface TimelineChartProps {
    events: TimelineEvent[];
    isLoading: boolean;
}

const getEventStyles = (type: TimelineEvent['type']) => {
    switch (type) {
        case 'filing': return { 
            icon: <DocumentIcon className="w-5 h-5 text-white/40" />,
            borderClass: 'border-l-white/20',
            label: 'FILING'
        };
        case 'motion': return {
            icon: <UserIcon className="w-5 h-5 text-white/40" />,
            borderClass: 'border-l-white/20',
            label: 'MOTION'
        };
        case 'court_date': return {
            icon: <CalendarIcon className="w-5 h-5 text-white" />,
            borderClass: 'border-l-white',
            label: 'COURT_DATE'
        };
        case 'ruling': return {
            icon: <GavelIcon className="w-5 h-5 text-white/60" />,
            borderClass: 'border-l-white/60',
            label: 'RULING'
        };
        default: return {
            icon: <SparklesIcon className="w-5 h-5 text-white/20" />,
            borderClass: 'border-l-white/5',
            label: 'EVENT'
        };
    }
}

export default function TimelineChart({ events, isLoading }: TimelineChartProps): React.ReactNode {
    if (isLoading) return null;
    if (!events || events.length === 0) return null;

    const sortedEvents = [...events].sort((a, b) => {
        try {
            return new Date(a.date).getTime() - new Date(b.date).getTime();
        } catch (e) {
            return 0;
        }
    });

    return (
        <div className="relative">
            <div className="flex items-center gap-6 mb-16">
                <div className="p-4 bg-white text-black">
                    <CalendarIcon className="w-8 h-8" />
                </div>
                <div>
                    <h4 className="text-3xl font-black text-white uppercase italic tracking-tighter">Temporal Vector Map</h4>
                    <p className="etched-label mt-1">SIGINT Chronological Nodes</p>
                </div>
            </div>

            <div className="relative pl-12 border-l border-white/5 space-y-16 ml-6">
                {sortedEvents.map((event, index) => {
                    const styles = getEventStyles(event.type);
                    return (
                        <div key={index} className="relative group">
                            <div className="absolute -left-[61px] top-0 w-12 h-12 flex items-center justify-center bg-black border border-white/20 text-white font-mono text-[10px] font-black z-10 group-hover:border-white transition-colors">
                                {index + 1}
                            </div>

                            <div className="flex items-center gap-6 mb-4">
                                <span className="font-mono font-black text-xs text-white bg-white/5 border border-white/10 px-4 py-1">
                                    {event.date}
                                </span>
                                <div className="flex items-center gap-3">
                                    {styles.icon}
                                    <span className="etched-label opacity-40 group-hover:opacity-100 transition-opacity">
                                        {styles.label}
                                    </span>
                                </div>
                            </div>

                            <div className={`p-8 bg-white/[0.02] border border-white/5 group-hover:border-white/20 transition-all border-l-4 ${styles.borderClass}`}>
                                <p className="text-xl text-white font-light italic leading-relaxed">
                                    "{event.description}"
                                </p>
                                {event.citation && (
                                    <p className="mt-6 text-[9px] text-[#666] font-mono uppercase tracking-[0.3em] border-t border-white/5 pt-4">
                                        SRC_ID: {event.citation}
                                    </p>
                                )}
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
}

