                  prose-strong:text-white prose-strong:font-black prose-strong:italic
                  prose-li:text-white/70 prose-li:mb-4 prose-li:text-2xl">
                  <ReactMarkdown remarkPlugins={[remarkGfm]}>{output.summary}</ReactMarkdown>
                  {output.isSummaryStreaming && <span className="inline-block w-3 h-10 bg-white animate-pulse align-middle ml-4"></span>}
                </div>
              </div>
            </div>

            {/* Strategic Adversarial Logic Widget */}
            <div className="break-inside-avoid mt-12">
              <AdversarialStrategyWidget strategy={output.adversarialStrategy} isLoading={output.isAdversarialLoading} />
            </div>

            {/* Judicial Nodes Grid */}
            <div className="grid grid-cols-1 xl:grid-cols-2 gap-12">
              {output.identifiedJudges && output.identifiedJudges.length > 0 && (
                <div className="break-inside-avoid">
                  <IdentifiedJudges judges={output.identifiedJudges} isLoading={output.isIdentifiedJudgesLoading} onJudgeClick={onJudgeClick} />
                </div>
              )}

              <div className="bg-white/5 border border-white/10 p-12 break-inside-avoid">
                <div className="flex items-center gap-4 mb-10 border-b border-white/10 pb-6">
                  <GlobeIcon className="w-6 h-6 text-white/40" />
                  <h4 className="etched-label text-[11px] font-black text-white/30 tracking-widest uppercase">Verified Source Logs</h4>
                </div>
                <div className="flex flex-col gap-6">
                  {output.sources.slice(0, 10).map((s, i) => (
                    <div key={i} className="flex items-center justify-between p-5 bg-[#0a0a0a] border border-white/5 hover:border-white/20 transition-all group">
                      <div className="flex items-center gap-6 truncate">
                        <span className="text-white/10 font-mono text-[10px]">0{i}</span>
                        <span className="truncate text-lg font-bold text-white/60 group-hover:text-white transition-colors uppercase tracking-widest italic">{s.title}</span>
                      </div>
                      <span className="etched-label text-[8px] opacity-10 ml-6 uppercase">SRC_VERIFIED</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Temporal Map */}
            {output.timelineEvents && output.timelineEvents.length > 0 && (
              <div className="break-inside-avoid mt-12 border-t border-white/10 pt-16">
                <TimelineChart events={output.timelineEvents} isLoading={output.isTimelineLoading} />
