            {/* Classified Footer (Styled specifically for the PDF report) */}
            <div className="mt-20 pt-10 border-t-2 border-white/10 text-center flex flex-col gap-4">
              <span className="etched-label text-white/20 tracking-[1.5em] text-[8px] font-black">
                END_OF_INTEL_TRANSMISSION // DOSSIER_{dossierId}
              </span>
              <span className="text-white/5 text-[6px] uppercase tracking-[0.5em] font-mono">
                GENERATED BY DENVER_INTEL PRECISION_ENGINE_CORE // DO NOT REPRODUCE WITHOUT AUTHORIZATION
              </span>
            </div>
          </div>

          {/* Interactive UI Sections (Excluded from the primary PDF dossier ref or placed below) */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-16 mt-8">
            <FollowUpQuestions questions={output.followUpQuestions || []} onQuestionClick={onQuestionClick} />
            <RelatedQueries queries={output.relatedQueries || []} onQueryClick={onQuestionClick} />
          </div>
        </div>
      ) : null}

      <style>{`
        .break-inside-avoid { 
          break-inside: avoid; 
          page-break-inside: avoid;
        }
        @media print {
          body { background-color: white !important; color: black !important; }
          .glass-card { background: white !important; border: 1px solid #ddd !important; color: black !important; box-shadow: none !important; }
          .etched-label { color: #555 !important; }
          .text-white { color: black !important; }
          .bg-white { background: black !important; color: white !important; }
          .bg-black { background: white !important; border: 1px solid #eee !important; }
          .border-white\\/5 { border-color: #eee !important; }
          .prose-invert { filter: invert(1); }
          .print-hidden { display: none !important; }
        }
      `}</style>
    </div>
  );
}

import React, { useState, useEffect, useRef, useLayoutEffect } from 'react';
import { SearchType, type SearchParams, DateRange } from '../types';
import SpinnerIcon from './icons/SpinnerIcon';
import HistoryIcon from './icons/HistoryIcon';
import { MAX_QUERY_LENGTH } from '../constants';

interface SearchFormProps {
  params: SearchParams;
  setParams: React.Dispatch<React.SetStateAction<SearchParams>>;
  onSearch: () => void;
  isLoading: boolean;
  onClear: () => void;
  onSelectHistory: (p: SearchParams) => void;
  onSave: () => void;
  canSave: boolean;
}

export default function SearchForm({ 
  params, 
  setParams, 
  onSearch, 
  isLoading, 
  onClear,
  onSelectHistory,
  onSave,
  canSave
}: SearchFormProps): React.ReactNode {
  const [isAdvancedOpen, setIsAdvancedOpen] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useLayoutEffect(() => {
    const textarea = textareaRef.current;
    if (textarea) {
      textarea.style.height = 'auto';
      textarea.style.height = `${Math.max(120, textarea.scrollHeight)}px`;
    }
  }, [params.query]);

  return (
    <div className="flex flex-col gap-0">
      {/* Tactical Input Header */}
      <div className="flex justify-between items-center px-12 py-6 border-b border-white/5 bg-white/[0.02]">
        <div className="flex items-center gap-6">
          <div className={`w-2 h-2 rounded-full ${isLoading ? 'bg-white animate-pulse' : 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]'}`}></div>
          <span className="etched-label tracking-[0.6em]">Neural_Input_Active</span>
        </div>
        <div className="flex gap-10">
          <span className="etched-label opacity-20">Payload: {params.query.length} / {MAX_QUERY_LENGTH}</span>
          <span className="etched-label opacity-20">Logic: Gemini_v3_Flash</span>
        </div>
      </div>

      <div className="p-12 space-y-12">
        {/* Main Query Field */}
        <div className="relative group">
          <textarea
            ref={textareaRef}
            value={params.query}
            onChange={(e) => setParams({...params, query: e.target.value})}
            placeholder="INPUT_MISSION_OBJECTIVE..."
            className="w-full bg-transparent border-none p-0 font-mono text-white text-5xl font-light focus:outline-none placeholder:text-white/5 resize-none tracking-tighter italic leading-tight"
            disabled={isLoading}
          />
          <div className="absolute -left-12 top-0 bottom-0 w-1 bg-gradient-to-b from-white/20 to-transparent"></div>
        </div>

        {/* Dynamic Parameter Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-8">
          <div className="flex flex-col gap-3">
            <label className="etched-label">Target_Entity</label>
            <input 
              type="text" 
              placeholder="NAME / CASE_ID" 
              value={params.partyName || ''} 
              onChange={(e) => setParams({...params, partyName: e.target.value})} 
              className="bg-white/5 border border-white/10 text-white text-xs p-5 outline-none focus:border-white/30 placeholder:text-white/10 uppercase tracking-widest font-black" 
            />
          </div>

          <div className="flex flex-col gap-3">
            <label className="etched-label">Temporal_Window</label>
            <select 
              value={params.dateRange} 
              onChange={(e) => setParams({...params, dateRange: e.target.value as DateRange})} 
              className="bg-white/5 border border-white/10 text-white text-xs p-5 outline-none focus:border-white/30 appearance-none cursor-pointer uppercase tracking-widest font-black"
            >
              <option value={DateRange.ANY}>Unrestricted</option>
              <option value={DateRange.DAY}>Past_24h</option>
              <option value={DateRange.WEEK}>Past_7d</option>
              <option value={DateRange.MONTH}>Past_30d</option>
              <option value={DateRange.YEAR}>Past_365d</option>
            </select>
          </div>

          <div className="flex flex-col gap-3">
            <label className="etched-label">Schema_Type</label>
            <select 
              value={params.caseType} 
              onChange={(e) => setParams({...params, caseType: e.target.value as any})} 
              className="bg-white/5 border border-white/10 text-white text-xs p-5 outline-none focus:border-white/30 appearance-none cursor-pointer uppercase tracking-widest font-black"
            >
              <option value="all">All_Objects</option>
              <option value="civil">Civil_Schema</option>
              <option value="criminal">Criminal_Schema</option>
              <option value="family">Family_Schema</option>
            </select>
          </div>

          <div className="flex flex-col gap-3">
            <label className="etched-label">Operational_Sector</label>
            <select 
              value={params.jurisdiction} 
              onChange={(e) => setParams({...params, jurisdiction: e.target.value as any})} 
              className="bg-white/5 border border-white/10 text-white text-xs p-5 outline-none focus:border-white/30 appearance-none cursor-pointer uppercase tracking-widest font-black"
            >
              <option value="all">Global_Denver</option>
              <option value="denver_district">District_Court</option>
              <option value="denver_county">County_Court</option>
            </select>
          </div>
        </div>

        {/* Command Actions */}
        <div className="flex flex-col md:flex-row items-stretch gap-6 pt-6">
          <button 
            onClick={onSearch}
            disabled={isLoading || !params.query.trim()}
            className="flex-grow group px-12 py-8 bg-white text-black font-black uppercase italic tracking-tighter text-4xl hover:bg-[#efefef] transition-all flex items-center justify-center gap-8 shadow-2xl overflow-hidden relative"
          >
            {isLoading ? (
              <>
                <SpinnerIcon className="w-8 h-8 animate-spin text-black" />
                <span className="animate-pulse">Synthesizing_Intelligence...</span>
              </>
            ) : (
              <>
                <span className="relative z-10">[Execute_Scan]</span>
                <div className="absolute inset-0 bg-white/50 translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-700 ease-in-out"></div>
              </>
            )}
          </button>

          <div className="flex gap-4">
            <button 
              onClick={onClear} 
              className="px-10 py-8 border border-white/10 text-white/40 etched-label hover:text-white hover:bg-white/5 transition-all"
            >
              Clear_Input
            </button>
            <button 
              onClick={() => {}} 
              className="px-10 py-8 border border-white/10 text-white/40 etched-label hover:text-white hover:bg-white/5 transition-all"
            >
              <HistoryIcon className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useRef, useMemo } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { type SearchResult, type SearchParams } from '../types';
import FollowUpQuestions from './FollowUpQuestions';
import BookmarkIcon from './icons/BookmarkIcon';
import BookmarkFilledIcon from './icons/BookmarkFilledIcon';
import DownloadIcon from './icons/DownloadIcon';
import RelatedQueries from './RelatedQueries';
import GlobeIcon from './icons/GlobeIcon';
import TimelineChart from './TimelineChart';
import IdentifiedJudges from './IdentifiedJudges';
import AdversarialStrategyWidget from './AdversarialStrategyWidget';
import SpinnerIcon from './icons/SpinnerIcon';

interface ResultsDisplayProps {
  output: SearchResult | null;
  searchParams: SearchParams | null;
  isLoading: boolean;
  onQuestionClick: (q: string) => void;
  onAnalysisClick: (p: string) => void;
  onSave: (p: SearchParams, r: SearchResult) => void;
  onRemoveSave: (p: SearchParams) => void;
  isSaved: boolean;
  onJudgeClick: (n: string) => void;
}

const IntelligenceSkeleton = () => (
  <div className="flex flex-col gap-16 animate-pulse p-12">
    <div className="space-y-6">
       <div className="h-4 bg-white/5 w-24"></div>
       <div className="h-16 bg-white/5 w-3/4"></div>
       <div className="h-40 bg-white/5 w-full"></div>
    </div>
  </div>
);

export default function ResultsDisplay({ output, searchParams, isLoading, onQuestionClick, onAnalysisClick, onSave, onRemoveSave, isSaved, onJudgeClick }: ResultsDisplayProps): React.ReactNode {
  const dossierRef = useRef<HTMLDivElement>(null);
  const [isExporting, setIsExporting] = useState(false);
  const dossierId = useMemo(() => Math.random().toString(16).substring(2, 8).toUpperCase(), []);

  const handleExportPDF = async () => {
    if (!dossierRef.current || !output) return;
    setIsExporting(true);
    const element = dossierRef.current;
    const opt = {
      margin: 10,
      filename: `DENVER_INTEL_REPORT_${dossierId}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 3, useCORS: true, backgroundColor: '#050505' },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
    };
    try {
      // @ts-ignore
      await html2pdf().set(opt).from(element).save();
    } finally {
      setIsExporting(false);
    }
  };

  if (!output && !isLoading) return null;

  return (
    <div className="flex flex-col gap-12 pb-24 entry-animation">
      {isLoading && (!output || !output.summary) ? (
        <IntelligenceSkeleton />
      ) : output ? (
        <div className="flex flex-col gap-12">
          {/* Dossier Container */}
          <div ref={dossierRef} className="flex flex-col gap-12 bg-black border border-white/5 p-12 shadow-2xl relative overflow-hidden">

            {/* Dossier Metadata Header */}
            <div className="flex justify-between items-start border-b border-white/10 pb-10 mb-6">
              <div className="flex flex-col gap-2">
                <span className="etched-label text-white/60">Intelligence_Dossier_Stream</span>
                <span className="text-4xl font-black text-white italic tracking-tighter uppercase leading-none">
                  Sector_Analysis: <span className="text-white/40">{searchParams?.query.substring(0, 30)}...</span>
                </span>
              </div>
              <div className="text-right flex flex-col gap-1">
                <span className="etched-label text-white/40">NODE: {dossierId}</span>
                <span className="etched-label text-white/40">TIMESTAMP: {new Date().toISOString()}</span>
              </div>
            </div>

            {/* INTEL_01: Operational Briefing */}
            <div className="relative group">
              <span className="section-index">INTEL_01</span>
              <div className="max-w-5xl">
                <div className="prose prose-invert prose-2xl max-w-none text-white leading-relaxed font-light
                  prose-h1:text-5xl prose-h1:font-black prose-h1:italic prose-h1:mb-12 prose-h1:tracking-tighter
                  prose-h2:text-[10px] prose-h2:text-white/40 prose-h2:uppercase prose-h2:tracking-[0.8em] prose-h2:border-b prose-h2:border-white/5 prose-h2:pb-6 prose-h2:mt-20 prose-h2:font-black
                  prose-p:mb-8 prose-p:text-2xl prose-p:font-light prose-p:leading-normal
                  prose-strong:text-white prose-strong:font-black prose-strong:italic
                  prose-li:text-white/80 prose-li:mb-4 prose-li:text-xl">
                  <ReactMarkdown remarkPlugins={[remarkGfm]}>{output.summary}</ReactMarkdown>
                  {output.isSummaryStreaming && <span className="inline-block w-2 h-8 bg-white animate-pulse align-middle ml-2"></span>}
                </div>
              </div>
            </div>

            {/* INTEL_02: Adversarial Mapping */}
            <div className="relative mt-12">
              <span className="section-index">INTEL_02</span>
              <AdversarialStrategyWidget strategy={output.adversarialStrategy} isLoading={output.isAdversarialLoading} />
            </div>

            {/* INTEL_03: Bench Analysis & Sources */}
            <div className="grid grid-cols-1 xl:grid-cols-2 gap-12 mt-12">
              {output.identifiedJudges && output.identifiedJudges.length > 0 && (
                <div className="relative">
                  <span className="section-index">INTEL_03A</span>
                  <IdentifiedJudges judges={output.identifiedJudges} isLoading={output.isIdentifiedJudgesLoading} onJudgeClick={onJudgeClick} />
                </div>
              )}

              <div className="bg-white/5 border border-white/10 p-12 relative">
                <span className="section-index">INTEL_03B</span>
                <div className="flex items-center gap-4 mb-10 border-b border-white/10 pb-6">
                  <GlobeIcon className="w-5 h-5 text-white/20" />
                  <h4 className="etched-label">Source_Nexus_Logs</h4>
                </div>
                <div className="flex flex-col gap-4">
                  {output.sources.slice(0, 8).map((s, i) => (
                    <div key={i} className="flex items-center justify-between p-4 bg-black/40 border border-white/5 hover:border-white/20 transition-all group">
                      <div className="flex items-center gap-6 truncate">
                        <span className="text-white/10 font-mono text-[9px]">0{i}</span>
                        <span className="truncate text-base font-bold text-white/40 group-hover:text-white transition-colors uppercase tracking-widest italic">{s.title}</span>
                      </div>
                      <a href={s.uri} target="_blank" rel="noreferrer" className="etched-label text-[8px] opacity-10 group-hover:opacity-100 transition-opacity">Launch_Link</a>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* INTEL_04: Temporal Vector */}
            {output.timelineEvents && output.timelineEvents.length > 0 && (
              <div className="relative mt-12">
                <span className="section-index">INTEL_04</span>
                <div className="border-t border-white/10 pt-16">
                  <TimelineChart events={output.timelineEvents} isLoading={output.isTimelineLoading} />
                </div>
              </div>
            )}

            {/* Dossier Footer Branding */}
            <div className="mt-20 pt-10 border-t border-white/10 text-center flex flex-col gap-2">
              <span className="etched-label text-white/10 tracking-[1.5em] font-black">End_Of_Intelligence_Transmission</span>
              <span className="text-white/5 text-[7px] uppercase font-mono">Precision_Engine_v4 // Denver_DCO_Intel_Sector</span>
            </div>
          </div>

          {/* Dossier Controls - Outside the print container */}
          <div className="flex justify-between items-center bg-white/5 p-6 border border-white/10">
            <div className="flex gap-4">
              <FollowUpQuestions questions={output.followUpQuestions || []} onQuestionClick={onQuestionClick} />
            </div>
            <div className="flex gap-4">
              <button 
                onClick={handleExportPDF}
                disabled={isExporting}
                className="flex items-center gap-4 px-8 py-4 bg-white text-black font-black hover:bg-[#efefef] transition-all disabled:opacity-50"
              >
                {isExporting ? <SpinnerIcon className="w-5 h-5 animate-spin" /> : <DownloadIcon className="w-5 h-5" />}
                <span className="etched-label text-black">Export_Dossier</span>
              </button>
              <button 
                onClick={() => isSaved ? onRemoveSave(searchParams!) : onSave(searchParams!, output)} 
                className={`p-4 border transition-all ${isSaved ? 'bg-white text-black border-white' : 'border-white/20 text-white hover:bg-white/10'}`}
              >
                {isSaved ? <BookmarkFilledIcon className="w-6 h-6" /> : <BookmarkIcon className="w-6 h-6" />}
              </button>
            </div>
          </div>
        </div>
      ) : null}

      <style>{`
        .prose blockquote { border-left-color: white; border-left-width: 4px; font-style: italic; color: rgba(255,255,255,0.7); padding-left: 2rem; }
        .prose a { color: white; text-decoration: underline; text-underline-offset: 4px; font-weight: 800; }
        .prose a:hover { text-decoration-thickness: 2px; }
      `}</style>
    </div>
  );
}

import React from 'react';
import { type AdversarialStrategy } from '../types';
import GavelIcon from './icons/GavelIcon';
import AlertIcon from './icons/AlertIcon';
import SparklesIcon from './icons/SparklesIcon';
import SpinnerIcon from './icons/SpinnerIcon';
import BrainCircuitIcon from './icons/BrainCircuitIcon';

interface AdversarialStrategyWidgetProps {
  strategy?: AdversarialStrategy;
  isLoading?: boolean;
}

export default function AdversarialStrategyWidget({ strategy, isLoading }: AdversarialStrategyWidgetProps): React.ReactNode {
  if (isLoading) {
    return (
      <div className="bg-white/5 p-24 flex flex-col items-center justify-center gap-10 border border-white/10">
        <SpinnerIcon className="w-12 h-12 animate-spin text-white/20" />
        <span className="etched-label animate-pulse">Running_Strategic_Simulation...</span>
      </div>
    );
  }

  if (!strategy || (!strategy.prosecutorMoves.length && !strategy.defenseCounters.length)) return null;

  return (
    <div className="bg-black/40 border border-white/5 p-12 relative">
      <div className="flex flex-col lg:flex-row justify-between items-start mb-16 gap-12 border-b border-white/5 pb-12">
        <div className="flex items-center gap-10">
          <div className="p-10 bg-white text-black">
            <BrainCircuitIcon className="w-10 h-10" />
          </div>
          <div>
            <h3 className="text-4xl font-black text-white tracking-tighter uppercase italic leading-none">Strategic_Matrix</h3>
            <span className="etched-label mt-2 opacity-40">Adversarial_Threat_Analysis</span>
          </div>
        </div>
        <div className="flex items-center gap-4 bg-red-950/20 border border-red-900/40 px-8 py-4 text-red-500 font-black text-xs tracking-widest uppercase">
          <AlertIcon className="w-4 h-4" /> Threat_Level: Critical
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-20">
        {/* Prosecution Logic */}
        <div className="space-y-12">
          <div className="flex items-center gap-4 border-l-4 border-red-600 pl-6">
            <h4 className="etched-label text-red-500">Aggressor_Vector (Prosecution)</h4>
          </div>
          <ul className="space-y-8">
            {strategy.prosecutorMoves.map((move, i) => (
              <li key={i} className="text-xl text-white/80 pl-6 border-l border-white/10 py-2 leading-relaxed font-bold italic group hover:border-red-600 transition-all">
                <span className="text-[7px] font-mono opacity-20 block mb-2">THREAD_0{i}</span> {move}
              </li>
            ))}
          </ul>
        </div>

        {/* Defense Logic */}
        <div className="space-y-12">
          <div className="flex items-center gap-4 border-l-4 border-blue-600 pl-6">
            <h4 className="etched-label text-blue-500">Counter_Protocol (Defense)</h4>
          </div>
          <ul className="space-y-8">
            {strategy.defenseCounters.map((counter, i) => (
              <li key={i} className="text-xl text-white pl-6 border-l border-white/20 py-2 leading-relaxed font-black uppercase italic tracking-tight group hover:bg-blue-600/5 transition-all">
                <span className="text-[7px] font-mono opacity-20 block mb-2">MANEUVER_0{i}</span> {counter}
              </li>
            ))}
          </ul>
        </div>
      </div>

      {/* Hidden Risks */}
      <div className="mt-16 p-8 bg-white/5 border border-white/10">
        <h4 className="etched-label text-white/20 mb-6">Predicted_System_Anomalies</h4>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {strategy.hiddenRisks.map((risk, i) => (
            <div key={i} className="text-xs text-white/40 font-medium italic border-l border-white/10 pl-6">
              {risk}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
